package com.projetok.domain.effect;

import com.projetok.domain.entity.Mob;
import com.projetok.domain.entity.Player;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.StatusEffectsComponent;
import com.projetok.domain.item.LootTable;
import com.projetok.domain.network.PlayerConnection;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Regressões do armazenamento, aplicação e relógio de efeitos sem interface ou habilidade. */
class StatusEffectServiceTest {
    private final StatusEffectService service = new StatusEffectService();

    /** Cria um mob mínimo sem depender da fábrica ou de componentes de combate. */
    private Mob mob() {
        var mob = new Mob(10, "Alvo", new Position(20, 30), LootTable.of());
        mob.attach(new HealthComponent(100));
        return mob;
    }

    /** Cria jogador com vida para verificar a restrição de congelamento. */
    private Player player() {
        var player = new Player(1, "Jogador", new Position(0, 0), new PlayerConnection() {
            @Override public void send(Object packet) { }
            @Override public void disconnect() { }
        });
        player.attach(new HealthComponent(100));
        return player;
    }

    /** Componente novo não inventa efeitos; a atualização sem componente não o anexa. */
    @Test void inicialmenteSemEfeitos() {
        var effects = new StatusEffectsComponent();
        assertFalse(effects.has(StatusEffectType.FREEZE));
        assertEquals(0f, effects.remaining(StatusEffectType.FREEZE));
        assertTrue(effects.snapshot().isEmpty());
        var mob = mob();
        service.update(mob, 1f);
        assertTrue(mob.get(StatusEffectsComponent.class).isEmpty());
    }

    /** Aplicação cria armazenamento compatível com entidades antigas e dura um segundo. */
    @Test void aplicacaoEDuracaoDeUmSegundo() {
        var mob = mob();
        assertTrue(service.apply(mob, StatusEffectType.FREEZE, 1f));
        var effects = mob.require(StatusEffectsComponent.class);
        assertTrue(effects.has(StatusEffectType.FREEZE));
        assertEquals(1f, effects.remaining(StatusEffectType.FREEZE));
        service.update(mob, 0f);
        assertEquals(1f, effects.remaining(StatusEffectType.FREEZE));
        service.update(mob, 0.4f);
        assertEquals(0.6f, effects.remaining(StatusEffectType.FREEZE), 0.000001f);
        service.update(mob, 0.59f);
        assertTrue(effects.has(StatusEffectType.FREEZE));
        service.update(mob, 0.01f);
        assertFalse(effects.has(StatusEffectType.FREEZE));
        assertEquals(0f, effects.remaining(StatusEffectType.FREEZE));
    }

    /** Novo sucesso restaura exatamente um segundo, sem somar à duração anterior. */
    @Test void renovacaoNaoAcumulaTempo() {
        var mob = mob();
        service.apply(mob, StatusEffectType.FREEZE, 1f);
        service.update(mob, 0.4f);
        var effects = mob.require(StatusEffectsComponent.class);
        assertEquals(0.6f, effects.remaining(StatusEffectType.FREEZE), 0.0001f);
        service.apply(mob, StatusEffectType.FREEZE, 1f);
        assertEquals(1f, effects.remaining(StatusEffectType.FREEZE));
        service.update(mob, 0.9f);
        assertTrue(effects.has(StatusEffectType.FREEZE));
        service.update(mob, 0.1f);
        assertFalse(effects.has(StatusEffectType.FREEZE));
    }

    /** Trinta passos da arena expiram o efeito sem deixar resíduos do arredondamento float. */
    @Test void expiraComDeltaDeTrintaHertz() {
        var mob = mob();
        service.apply(mob, StatusEffectType.FREEZE, 1f);
        for (int i = 0; i < 29; i++) service.update(mob, 1f / 30f);
        assertTrue(mob.require(StatusEffectsComponent.class).has(StatusEffectType.FREEZE));
        service.update(mob, 1f / 30f);
        assertFalse(mob.require(StatusEffectsComponent.class).has(StatusEffectType.FREEZE));
    }

    /** Mortos não recebem efeito novo e a atualização limpa um efeito anterior à morte. */
    @Test void mortoNaoRecebeELimpaEfeitoAnterior() {
        var mob = mob();
        service.apply(mob, StatusEffectType.FREEZE, 1f);
        service.update(mob, 0.3f);
        mob.receiveDamage(100);
        assertFalse(service.apply(mob, StatusEffectType.FREEZE, 1f));
        assertEquals(0.7f, mob.require(StatusEffectsComponent.class).remaining(StatusEffectType.FREEZE), 0.000001f);
        service.update(mob, 0f);
        assertTrue(mob.require(StatusEffectsComponent.class).snapshot().isEmpty());
        var alreadyDead = mob();
        alreadyDead.receiveDamage(100);
        assertFalse(service.apply(alreadyDead, StatusEffectType.FREEZE, 1f));
        assertTrue(alreadyDead.get(StatusEffectsComponent.class).isEmpty());
    }

    /** Congelamento de jogadores fica fora do escopo e não anexa componente. */
    @Test void jogadorNaoRecebeCongelamento() {
        var player = player();
        assertFalse(service.apply(player, StatusEffectType.FREEZE, 1f));
        assertTrue(player.get(StatusEffectsComponent.class).isEmpty());
        assertEquals(100, player.require(HealthComponent.class).current());
    }

    /** Cópias do mapa não aceitam alterações e não acompanham futuras mutações. */
    @Test void snapshotImutavelEIndependente() {
        var effects = new StatusEffectsComponent();
        effects.refresh(StatusEffectType.FREEZE, 1f);
        var snapshot = effects.snapshot();
        assertThrows(UnsupportedOperationException.class, () -> snapshot.clear());
        effects.advance(0.5f);
        assertEquals(1.0, snapshot.get(StatusEffectType.FREEZE));
        assertEquals(0.5f, effects.remaining(StatusEffectType.FREEZE));
        effects.clear();
        assertTrue(effects.snapshot().isEmpty());
        assertEquals(1, snapshot.size());
    }

    /** Durações inválidas falham antes de anexar ou renovar o armazenamento. */
    @Test void rejeitaDuracoesInvalidasSemMutacao() {
        var mob = mob();
        var component = new StatusEffectsComponent();
        for (float invalid : new float[] {0f, -1f, Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY}) {
            assertThrows(IllegalArgumentException.class, () -> service.apply(mob, StatusEffectType.FREEZE, invalid));
            assertThrows(IllegalArgumentException.class, () -> component.refresh(StatusEffectType.FREEZE, invalid));
            assertTrue(mob.get(StatusEffectsComponent.class).isEmpty());
            assertTrue(component.snapshot().isEmpty());
        }
        service.apply(mob, StatusEffectType.FREEZE, 1f);
        assertThrows(IllegalArgumentException.class, () -> service.apply(mob, StatusEffectType.FREEZE, Float.NaN));
        assertEquals(1f, mob.require(StatusEffectsComponent.class).remaining(StatusEffectType.FREEZE));
    }

    /** Deltas inválidos não removem efeitos nem alteram seu tempo restante. */
    @Test void rejeitaDeltasInvalidosSemMutacao() {
        var mob = mob();
        service.apply(mob, StatusEffectType.FREEZE, 1f);
        var effects = mob.require(StatusEffectsComponent.class);
        for (float invalid : new float[] {-1f, Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY}) {
            assertThrows(IllegalArgumentException.class, () -> service.update(mob, invalid));
            assertThrows(IllegalArgumentException.class, () -> effects.advance(invalid));
            assertEquals(1f, effects.remaining(StatusEffectType.FREEZE));
        }
        service.update(mob, Float.MAX_VALUE);
        assertFalse(effects.has(StatusEffectType.FREEZE));
    }
}

package com.projetok.domain.movement;

import com.projetok.domain.entity.DialogueScript;
import com.projetok.domain.entity.Npc;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import java.util.List;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Políticas filtram categorias sem duplicar a geometria normal ou a varredura contínua. */
class CollisionPolicyTest {
    private static final float RADIUS = 18f;
    private static final CollisionPolicy PHASE = CollisionPolicy.PHASE_THROUGH_ACTORS_AND_SOFT;

    /** Cria um corpo com vida sem depender de fábricas de habilidades. */
    private static Npc actor(int id, float x, float y) {
        var actor = new Npc(id, "Corpo de teste", new Position(x, y), DialogueScript.of("Corpo de teste"));
        actor.attach(new HealthComponent(100));
        return actor;
    }

    /** Obstáculos antigos conservam a classificação sólida do cenário original. */
    @Test void obstaculoSemCategoriaContinuaSolido() {
        var obstacle = new CollisionService.Obstacle(180f, 60f, 30f, 80f);
        assertEquals(CollisionCategory.SOLID_OBSTACLE, obstacle.category());
        var player = actor(1, 100f, 100f);
        var space = new CollisionService.Space(960f, 640f, List.of(obstacle), List.of());
        assertFalse(new CollisionService().isFree(player, 190f, 100f, RADIUS, space, PHASE));
    }

    /** A mesma posição é livre para passagem seletiva e ocupada para a física normal. */
    @Test void consultaSeletivaIgnoraAtoresEArbustosMasPreservaLimites() {
        var player = actor(1, 100f, 100f);
        var blocker = actor(2, 200f, 100f);
        var space = new CollisionService.Space(960f, 640f,
                List.of(new CollisionService.Obstacle(180f, 80f, 40f, 40f, CollisionCategory.SOFT_OBSTACLE)),
                List.of(new CollisionService.Body(blocker, 19f)));
        var collisions = new CollisionService();
        assertFalse(collisions.isFree(player, 200f, 100f, RADIUS, space));
        assertFalse(collisions.isFree(player, 200f, 100f, RADIUS, space, CollisionPolicy.SOLID));
        assertTrue(collisions.isFree(player, 200f, 100f, RADIUS, space, PHASE));
        for (Position outside : List.of(new Position(17f, 100f), new Position(943f, 100f),
                new Position(100f, 17f), new Position(100f, 623f))) {
            assertFalse(collisions.isFree(player, outside.x(), outside.y(), RADIUS, space, PHASE));
        }
    }

    /** Paredes finas ou espessas detêm até deslocamentos que atravessariam toda a forma. */
    @Test void varreduraSeletivaMantemParedesFinasEEspessas() {
        var collisions = new CollisionService();
        for (float thickness : new float[] {1f, 80f}) {
            var player = actor(1, 100f, 100f);
            var space = new CollisionService.Space(960f, 640f,
                    List.of(new CollisionService.Obstacle(200f, 50f, thickness, 100f)), List.of());
            collisions.resolveContinuous(player, 700f, 0f, RADIUS, space, PHASE);
            assertEquals(new Position(182f, 100f), player.getPosition());
            assertTrue(collisions.isFree(player, 182f, 100f, RADIUS, space));
        }
    }

    /** A política seletiva preserva o deslizamento por eixo ao atingir um sólido. */
    @Test void varreduraSeletivaDeslizaNoEixoLivre() {
        var player = actor(1, 100f, 100f);
        var space = new CollisionService.Space(960f, 640f,
                List.of(new CollisionService.Obstacle(160f, 0f, 2f, 640f)), List.of());
        new MovementService(new CollisionService()).moveContinuous(player, 100f, 100f, RADIUS, space, PHASE);
        assertEquals(new Position(142f, 200f), player.getPosition());
    }

    /** As quatro bordas continuam sólidas, inclusive em deslocamento diagonal contínuo. */
    @Test void varreduraSeletivaMantemLimitesNosDoisSentidos() {
        var player = actor(1, 900f, 580f);
        var space = new CollisionService.Space(960f, 640f, List.of(), List.of());
        var movement = new MovementService(new CollisionService());
        movement.moveContinuous(player, 300f, 300f, RADIUS, space, PHASE);
        assertEquals(new Position(942f, 622f), player.getPosition());
        movement.moveContinuous(player, -2000f, -2000f, RADIUS, space, PHASE);
        assertEquals(new Position(18f, 18f), player.getPosition());
    }

    /** O caminho normal utilizado pelo WASD continua tratando arbustos como bloqueadores. */
    @Test void movimentoNormalContinuaBloqueadoPorObstaculosLeves() {
        var player = actor(1, 100f, 100f);
        var space = new CollisionService.Space(960f, 640f,
                List.of(new CollisionService.Obstacle(140f, 80f, 30f, 40f, CollisionCategory.SOFT_OBSTACLE)),
                List.of());
        var movement = new MovementService(new CollisionService());
        movement.move(player, 50f, 0f, RADIUS, space);
        assertEquals(new Position(100f, 100f), player.getPosition());
        movement.moveContinuous(player, 150f, 0f, RADIUS, space);
        assertEquals(new Position(122f, 100f), player.getPosition());
    }
}

package com.projetok.domain.movement;

import com.projetok.domain.entity.DialogueScript;
import com.projetok.domain.entity.Npc;
import com.projetok.domain.entity.Position;
import java.util.List;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Casos geométricos da saída seletiva, separados da habilidade e do teste reservado. */
class CollisionRecoveryTest {
    private static final float RADIUS = 18f;

    /** Monta um ator sólido sem exigir componentes de combate para um NPC. */
    private Npc actor(float x, float y) {
        return new Npc(1, "Trajetória", new Position(x, y), DialogueScript.of("Teste"));
    }

    /** Uma curva segura é refeita por eixos; sua corda atravessaria a construção. */
    @Test void recuperaPelaCurvaRealAoRedorDaConstrucao() {
        var actor = actor(200f, 200f);
        var space = new CollisionService.Space(960f, 640f, List.of(
                new CollisionService.Obstacle(130f, 130f, 40f, 40f),
                new CollisionService.Obstacle(190f, 80f, 40f, 140f, CollisionCategory.SOFT_OBSTACLE)),
                List.of());
        var recovery = new CollisionService().recoverAlongPath(actor, List.of(
                new Position(100f, 100f), new Position(200f, 100f), new Position(200f, 200f)),
                RADIUS, space);
        assertTrue(recovery.recovered());
        assertEquals(new Position(172f, 100f), actor.getPosition());
        assertEquals(List.of(new Position(200f, 200f), new Position(200f, 100f),
                new Position(172f, 100f)), recovery.path());
        assertThrows(UnsupportedOperationException.class, () -> recovery.path().clear());
    }

    /** Uma parede no caminho de retorno impede aproveitar uma saída livre do outro lado. */
    @Test void recuoNaoUsaSaidaAlemDeParedeQueSurgiuNoPercurso() {
        var actor = actor(250f, 100f);
        var body = new CollisionService.Body(actor, RADIUS);
        var bodies = List.of(body);
        var index = new SpatialBodyIndex(bodies, 16f);
        var space = new CollisionService.Space(960f, 640f, List.of(
                new CollisionService.Obstacle(210f, 0f, 2f, 200f),
                new CollisionService.Obstacle(240f, 80f, 30f, 40f, CollisionCategory.SOFT_OBSTACLE)),
                bodies, index);
        var recovery = new CollisionService().recoverAlongPath(actor,
                List.of(new Position(100f, 100f), actor.getPosition()), RADIUS, space);
        assertFalse(recovery.recovered());
        assertEquals(new Position(250f, 100f), actor.getPosition());
        assertEquals(List.of(actor.getPosition()), recovery.path());
        assertTrue(index.query(250, 100, 250, 100).contains(body));
    }

    /** A tangência compartilhada continua sendo uma saída válida, mesmo sem vão de um pixel. */
    @Test void encontraTangenciaEntreDoisIntervalosEncostados() {
        var actor = actor(250f, 100f);
        var space = new CollisionService.Space(960f, 640f, List.of(
                new CollisionService.Obstacle(80f, 80f, 82f, 40f, CollisionCategory.SOFT_OBSTACLE),
                new CollisionService.Obstacle(198f, 80f, 100f, 40f, CollisionCategory.SOFT_OBSTACLE)),
                List.of());
        var recovery = new CollisionService().recoverAlongPath(actor,
                List.of(new Position(50f, 100f), actor.getPosition()), RADIUS, space);
        assertTrue(recovery.recovered());
        assertEquals(new Position(180f, 100f), actor.getPosition());
        assertTrue(new CollisionService().isFree(actor, 180f, 100f, RADIUS, space));
    }

    /** Rotas incompletas, diagonais ou não finitas são rejeitadas antes de corrigir posição. */
    @Test void rejeitaRotasInvalidasSemMutacao() {
        var actor = actor(250f, 100f);
        var origin = actor.getPosition();
        var space = new CollisionService.Space(960f, 640f, List.of(), List.of());
        var collisions = new CollisionService();
        for (var path : List.of(List.<Position>of(), List.of(new Position(100f, 100f)),
                List.of(new Position(100f, 200f), origin),
                List.of(new Position(Float.NaN, 100f), origin))) {
            assertThrows(IllegalArgumentException.class,
                    () -> collisions.recoverAlongPath(actor, path, RADIUS, space));
            assertEquals(origin, actor.getPosition());
        }
    }
}

package com.projetok.domain.movement;

import com.projetok.domain.combat.CombatService;
import com.projetok.domain.effect.StatusEffectService;
import com.projetok.domain.effect.StatusEffectType;
import com.projetok.domain.entity.Mob;
import com.projetok.domain.entity.Player;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.CombatComponent;
import com.projetok.domain.entity.component.EquipmentComponent;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.RaceComponent;
import com.projetok.domain.entity.component.StatsComponent;
import com.projetok.domain.entity.component.StatusEffectsComponent;
import com.projetok.domain.event.GameEventBus;
import com.projetok.domain.item.LootTable;
import com.projetok.domain.network.PlayerConnection;
import com.projetok.domain.race.RaceRegistry;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/** Comprova imobilização autoritativa sem interferir em dano, jogadores ou validação. */
class FreezeMovementTest {
    private final MovementService movement = new MovementService(new CollisionService());
    private final StatusEffectService effects = new StatusEffectService();
    private final CollisionService.Space space = new CollisionService.Space(1000, 1000, List.of(), List.of());
    private final Mob mob = mob();

    /** Monta um mob desarmado real com vida e atributos suficientes para atacar. */
    private static Mob mob() {
        Mob mob = new Mob(10, "Mob", new Position(200, 200), LootTable.of());
        mob.attach(new HealthComponent(120));
        mob.attach(new RaceComponent(RaceRegistry.withDefaults().get("demon")));
        mob.attach(new StatsComponent(5, 5, 5, 1, 0));
        mob.attach(new EquipmentComponent());
        mob.attach(new CombatComponent(null));
        return mob;
    }

    /** Cria jogador neutro ao dano físico recebido do mob. */
    private static Player player() {
        Player player = new Player(1, "Jogador", new Position(240, 200), new PlayerConnection() {
            @Override public void send(Object packet) { }
            @Override public void disconnect() { }
        });
        player.attach(new HealthComponent(100));
        player.attach(new RaceComponent(RaceRegistry.withDefaults().get("human")));
        return player;
    }

    // --- Bloqueio nos caminhos públicos de movimentação ---

    /** Deslocamentos diretos, direcionados e contínuos não mudam a posição congelada. */
    @Test void freezeBloqueiaTodosOsCaminhosDeMovimento() {
        assertTrue(effects.apply(mob, StatusEffectType.FREEZE, 1f));
        Position original = mob.getPosition();

        movement.move(mob, 30, 20, 19, space);
        assertEquals(original, mob.getPosition());
        movement.moveDirected(mob, movement.direction(1, 1), 92, 0.5f, 19, space);
        assertEquals(original, mob.getPosition());
        movement.moveContinuous(mob, 200, 200, 19, space);
        assertEquals(original, mob.getPosition());
        assertEquals(1f, mob.require(StatusEffectsComponent.class).remaining(StatusEffectType.FREEZE));
    }

    /** O movimento é retomado apenas quando o segundo inteiro do efeito expira. */
    @Test void movimentoRetornaAposExpirarUmSegundo() {
        effects.apply(mob, StatusEffectType.FREEZE, 1f);
        effects.update(mob, 0.75f);
        movement.move(mob, 10, 0, 19, space);
        assertEquals(new Position(200, 200), mob.getPosition());
        assertEquals(0.25f, mob.require(StatusEffectsComponent.class).remaining(StatusEffectType.FREEZE));

        effects.update(mob, 0.25f);
        assertFalse(mob.require(StatusEffectsComponent.class).has(StatusEffectType.FREEZE));
        movement.move(mob, 10, 0, 19, space);
        assertEquals(new Position(210, 200), mob.getPosition());
        movement.moveDirected(mob, new Position(0, 1), 20, 0.5f, 19, space);
        assertEquals(new Position(210, 210), mob.getPosition());
        movement.moveContinuous(mob, 10, 0, 19, space);
        assertEquals(new Position(220, 210), mob.getPosition());
    }

    /** Freeze não transforma entradas inválidas em comandos aceitos silenciosamente. */
    @Test void entradasInvalidasContinuamRejeitadasDuranteFreeze() {
        effects.apply(mob, StatusEffectType.FREEZE, 1f);
        Position original = mob.getPosition();
        for (float invalid : new float[] {Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY}) {
            assertThrows(IllegalArgumentException.class, () -> movement.move(mob, invalid, 0, 19, space));
            assertThrows(IllegalArgumentException.class, () -> movement.move(mob, 0, invalid, 19, space));
            assertThrows(IllegalArgumentException.class, () -> movement.moveContinuous(mob, invalid, 0, 19, space));
            assertThrows(IllegalArgumentException.class,
                    () -> movement.moveDirected(mob, new Position(invalid, 0), 92, 0.1f, 19, space));
            assertThrows(IllegalArgumentException.class,
                    () -> movement.moveDirected(mob, new Position(1, 0), invalid, 0.1f, 19, space));
            assertThrows(IllegalArgumentException.class,
                    () -> movement.moveDirected(mob, new Position(1, 0), 92, invalid, 19, space));
        }
        for (float radius : new float[] {0, -1, Float.NaN, Float.POSITIVE_INFINITY}) {
            assertThrows(IllegalArgumentException.class, () -> movement.move(mob, 1, 0, radius, space));
            assertThrows(IllegalArgumentException.class,
                    () -> movement.moveContinuous(mob, 1, 0, radius, space));
        }
        assertThrows(IllegalArgumentException.class,
                () -> movement.moveDirected(mob, new Position(1, 0), -1, 0.1f, 19, space));
        assertThrows(IllegalArgumentException.class,
                () -> movement.moveDirected(mob, new Position(1, 0), 92, -1, 19, space));
        assertEquals(original, mob.getPosition());
    }

    /** A imobilização não muda o cálculo nem impede o mob de causar dano normal. */
    @Test void mobCongeladoMantemAtaqueEDano() {
        Player target = player();
        CombatService combat = new CombatService(new GameEventBus());
        int damageBefore = combat.attack(mob, target);
        assertTrue(damageBefore > 0);

        effects.apply(mob, StatusEffectType.FREEZE, 1f);
        int damageDuring = combat.attack(mob, target);

        assertEquals(damageBefore, damageDuring);
        assertEquals(100 - damageBefore - damageDuring, target.require(HealthComponent.class).current());
        assertTrue(mob.require(StatusEffectsComponent.class).has(StatusEffectType.FREEZE));
        assertEquals(new Position(200, 200), mob.getPosition());
    }

    /** Mesmo um componente fabricado não permite congelamento de jogadores nesta tarefa. */
    @Test void freezeNaoBloqueiaJogadorComComponenteAnexadoManualmente() {
        Player player = player();
        StatusEffectsComponent fabricated = new StatusEffectsComponent();
        fabricated.refresh(StatusEffectType.FREEZE, 1f);
        player.attach(fabricated);

        movement.move(player, 10, 0, 18, space);
        assertEquals(new Position(250, 200), player.getPosition());
        movement.moveDirected(player, new Position(0, 1), 20, 0.5f, 18, space);
        assertEquals(new Position(250, 210), player.getPosition());
        movement.moveContinuous(player, 10, 0, 18, space);
        assertEquals(new Position(260, 210), player.getPosition());
    }
}

package com.projetok.domain.movement;

import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

/** Entradas inválidas e varredura sem tunelamento, executadas sem interface. */
class MovementHardeningTest {
    private final CollisionService collisions = new CollisionService();
    private final MovementService movement = new MovementService(collisions);

    /** Cria um ator mínimo. */
    private GameEntity actor(float x, float y) {
        var entity = new GameEntity(1, "Ator", new Position(x, y)) { };
        entity.attach(new HealthComponent(10));
        return entity;
    }

    /** Cenário sem corpos adicionais. */
    private CollisionService.Space space(CollisionService.Obstacle... obstacles) {
        return new CollisionService.Space(200, 200, List.of(obstacles), List.of());
    }

    /** Nenhum eixo pode ser aplicado antes da validação de todos os números. */
    @Test
    void rejeitaNaoFinitosSemMutacaoParcial() {
        var a = actor(20, 20);
        for (float invalid : new float[] {Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY}) {
            assertThrows(IllegalArgumentException.class, () -> collisions.isFree(a, invalid, 20, 5, space()));
            assertThrows(IllegalArgumentException.class, () -> collisions.isFree(a, 20, invalid, 5, space()));
            assertThrows(IllegalArgumentException.class, () -> collisions.isFree(a, 20, 20, invalid, space()));
            assertThrows(IllegalArgumentException.class, () -> movement.direction(invalid, 1));
            assertThrows(IllegalArgumentException.class, () -> movement.move(a, 5, invalid, 5, space()));
            assertThrows(IllegalArgumentException.class, () -> movement.moveContinuous(a, 5, invalid, 5, space()));
            assertThrows(IllegalArgumentException.class, () -> movement.moveDirected(a,
                    new Position(1, 0), invalid, 0.1f, 5, space()));
            assertThrows(IllegalArgumentException.class, () -> movement.moveDirected(a,
                    new Position(1, 0), 10, invalid, 5, space()));
            assertEquals(new Position(20, 20), a.getPosition());
        }
    }

    /** Overflow de posição e de velocidade também falha antes da resolução. */
    @Test
    void rejeitaOverflowENegativos() {
        var a = actor(Float.MAX_VALUE, 20);
        assertThrows(IllegalArgumentException.class, () -> movement.move(a, Float.MAX_VALUE, 5, 5, space()));
        assertEquals(new Position(Float.MAX_VALUE, 20), a.getPosition());
        var b = actor(20, 20);
        assertThrows(IllegalArgumentException.class, () -> movement.moveDirected(b,
                new Position(1, 0), Float.MAX_VALUE, 2, 5, space()));
        assertThrows(IllegalArgumentException.class, () -> movement.moveDirected(b,
                new Position(1, 0), -1, 1, 5, space()));
        assertThrows(IllegalArgumentException.class, () -> movement.moveDirected(b,
                new Position(1, 0), 1, -1, 5, space()));
        assertThrows(IllegalArgumentException.class, () -> collisions.resolve(b, 1, 1, 0, space()));
        assertEquals(new Position(20, 20), b.getPosition());
    }

    /** Geometria inválida não pode entrar no contexto. */
    @Test
    void validaGeometriaEOrigem() {
        assertThrows(IllegalArgumentException.class, () -> new CollisionService.Space(Float.NaN, 100, List.of(), List.of()));
        assertThrows(IllegalArgumentException.class, () -> new CollisionService.Space(100, -1, List.of(), List.of()));
        assertThrows(IllegalArgumentException.class, () -> new CollisionService.Obstacle(0, 0, -1, 1));
        assertThrows(IllegalArgumentException.class, () -> new CollisionService.Obstacle(Float.MAX_VALUE, 0, Float.MAX_VALUE, 1));
        assertThrows(IllegalArgumentException.class, () -> new CollisionService.Body(actor(0, 0), -1));
        var a = actor(Float.NaN, 10);
        assertThrows(IllegalArgumentException.class, () -> collisions.resolve(a, 1, 0, 5, space()));
        assertTrue(Float.isNaN(a.getPosition().x()));
    }

    /** Normalização extrema não produz vetor zero por overflow. */
    @Test
    void normalizaMagnitudeExtrema() {
        var d = movement.direction(Float.MAX_VALUE, Float.MAX_VALUE);
        assertEquals(1, Math.hypot(d.x(), d.y()), 0.000001);
        var tiny = movement.direction(Float.MIN_VALUE, Float.MIN_VALUE);
        assertEquals(1, Math.hypot(tiny.x(), tiny.y()), 0.000001);
    }

    /** Amostra o percurso inteiro, incluindo cantos arredondados e contatos fracionários. */
    @Test
    void trajetosContinuosNaoPenetramGeometria() {
        var context = space(new CollisionService.Obstacle(40, 40, 20, 20),
                new CollisionService.Obstacle(100, 10, 1, 170));
        var random = new java.util.Random(412);
        for (int trial = 0; trial < 100; trial++) {
            float x = 10 + random.nextFloat() * 180, y = 10 + random.nextFloat() * 180;
            var a = actor(x, y);
            if (!collisions.isFree(a, x, y, 5, context)) continue;
            collisions.resolveContinuous(a, random.nextFloat() * 300 - 150,
                    random.nextFloat() * 300 - 150, 5, context);
            var end = a.getPosition();
            for (int i = 0; i <= 100; i++) {
                float progress = i / 100f;
                // Interpolação em double e saturação evitam ultrapassar o contato por arredondamento.
                float sampledX = (float) ((double) x + ((double) end.x() - x) * progress);
                float sampledY = (float) ((double) y + ((double) end.y() - y) * progress);
                assertTrue(collisions.isFree(a, sampledX, y, 5, context));
                assertTrue(collisions.isFree(a, end.x(), sampledY, 5, context));
            }
        }
    }

    /** O caminho discreto fica compatível, enquanto o contínuo para na parede fina. */
    @Test
    void impedeTunelamentoNosDoisSentidos() {
        var wall = new CollisionService.Obstacle(50, 0, 1, 100);
        var a = actor(20, 30);
        collisions.resolve(a, 100, 0, 5, space(wall));
        assertEquals(120, a.getPosition().x());
        a.setPosition(new Position(20, 30));
        movement.moveContinuous(a, 100, 0, 5, space(wall));
        assertEquals(45, a.getPosition().x());
        a.setPosition(new Position(120, 30));
        movement.moveContinuous(a, -100, 0, 5, space(wall));
        assertEquals(56, a.getPosition().x());
    }

    /** Varredura vertical e deslizamento preservam a prioridade X antes de Y. */
    @Test
    void varreVerticalEDesliza() {
        var a = actor(20, 20);
        collisions.resolveContinuous(a, 0, 100, 5, space(new CollisionService.Obstacle(0, 50, 100, 1)));
        assertEquals(new Position(20, 45), a.getPosition());
        a.setPosition(new Position(20, 20));
        collisions.resolveContinuous(a, 100, 40, 5, space(new CollisionService.Obstacle(50, 0, 1, 100)));
        assertEquals(new Position(45, 60), a.getPosition());
    }

    /** Cantos são arredondados pela geometria circular; trajetória tangente é livre. */
    @Test
    void respeitaCantoETangencia() {
        var wall = new CollisionService.Obstacle(40, 40, 20, 20);
        var a = actor(20, 36);
        collisions.resolveContinuous(a, 70, 0, 5, space(wall));
        assertEquals(37, a.getPosition().x(), 0.0001);
        a.setPosition(new Position(20, 35));
        collisions.resolveContinuous(a, 70, 0, 5, space(wall));
        assertEquals(90, a.getPosition().x());
    }

    /** Entidades vivas bloqueiam o trajeto, mortas não bloqueiam. */
    @Test
    void varreCirculosSemTunelamento() {
        var a = actor(20, 30);
        var b = actor(70, 30);
        var context = new CollisionService.Space(200, 200, List.of(), List.of(new CollisionService.Body(b, 7)));
        collisions.resolveContinuous(a, 100, 0, 5, context);
        assertEquals(58, a.getPosition().x());
        b.require(HealthComponent.class).applyDamage(10);
        collisions.resolveContinuous(a, 100, 0, 5, context);
        assertEquals(158, a.getPosition().x());
    }

    /** O contato mais próximo prevalece, independentemente da ordem dos obstáculos. */
    @Test
    void contatoMaisProximoELimites() {
        var a = actor(20, 30);
        collisions.resolveContinuous(a, 150, 0, 5, space(
                new CollisionService.Obstacle(100, 0, 1, 100), new CollisionService.Obstacle(50, 0, 1, 100)));
        assertEquals(45, a.getPosition().x());
        a.setPosition(new Position(20, 30));
        collisions.resolveContinuous(a, 1000, -1000, 5, space());
        assertEquals(new Position(195, 5), a.getPosition());
    }

    /** A varredura não tenta corrigir uma origem já penetrada. */
    @Test
    void origemPenetradaFalhaSemMutacao() {
        var a = actor(45, 45);
        assertThrows(IllegalStateException.class, () -> collisions.resolveContinuous(a, 10, 10, 5,
                space(new CollisionService.Obstacle(40, 40, 20, 20))));
        assertEquals(new Position(45, 45), a.getPosition());
    }
}

package com.projetok.domain.movement;

import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import org.junit.jupiter.api.Test;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

/** Regressões geométricas executadas sem interface gráfica. */
class MovementServiceTest {
    private final CollisionService collisions = new CollisionService();
    private final MovementService movement = new MovementService(collisions);

    private GameEntity actor(int id, float x, float y) {
        GameEntity actor = new GameEntity(id, "Actor", new Position(x, y)) { };
        actor.attach(new HealthComponent(10));
        return actor;
    }

    /** Verifica velocidade e delta de tempo nos quatro sentidos e nas diagonais. */
    @Test
    void calculaDeslocamentoHorizontalVerticalEDiagonal() {
        var space = new CollisionService.Space(1000, 1000, List.of(), List.of());
        for (int x = -1; x <= 1; x++) for (int y = -1; y <= 1; y++) {
            var a = actor(1, 500, 500);
            var direction = movement.direction(x, y);
            movement.moveDirected(a, direction, 215f, 1f / 30f, 18f, space);
            assertEquals(500f + direction.x() * 215f * (1f / 30f), a.getPosition().x());
            assertEquals(500f + direction.y() * 215f * (1f / 30f), a.getPosition().y());
            assertEquals(x == 0 && y == 0 ? 0 : 215f / 30f,
                    Math.hypot(a.getPosition().x() - 500, a.getPosition().y() - 500), 0.0001);
        }
    }

    /** A resolução também pode ser usada diretamente pelo servidor. */
    @Test
    void resolucaoDiretaPreservaLimitesEDeslizamento() {
        var a = actor(1, 10, 10);
        var space = new CollisionService.Space(100, 100, List.of(), List.of());
        collisions.resolve(a, -6, 3, 5, space);
        assertEquals(new Position(10, 13), a.getPosition());
        collisions.resolve(a, -5, 0, 5, space);
        assertEquals(new Position(5, 13), a.getPosition());
    }

    @Test
    void normalizesAllDirectionsAndPreservesZero() {
        assertEquals(new Position(0, 0), movement.direction(0, 0));
        for (int x = -1; x <= 1; x++) for (int y = -1; y <= 1; y++) {
            if (x == 0 && y == 0) continue;
            Position d = movement.direction(x, y);
            assertEquals(1, Math.hypot(d.x(), d.y()), 0.000001);
            assertEquals(Math.signum(x), Math.signum(d.x()));
            assertEquals(Math.signum(y), Math.signum(d.y()));
        }
    }

    @Test
    void allowsBoundaryTangencyAndRejectsOutsideEachEdge() {
        var a = actor(1, 10, 10);
        var space = new CollisionService.Space(100, 80, List.of(), List.of());
        assertTrue(collisions.isFree(a, 5, 5, 5, space));
        assertTrue(collisions.isFree(a, 95, 75, 5, space));
        assertFalse(collisions.isFree(a, 4.99f, 10, 5, space));
        assertFalse(collisions.isFree(a, 10, 4.99f, 5, space));
        assertFalse(collisions.isFree(a, 95.01f, 10, 5, space));
        assertFalse(collisions.isFree(a, 10, 75.01f, 5, space));
    }

    @Test
    void slidesAlongWallAndResolvesXBeforeY() {
        var a = actor(1, 25, 40);
        var wall = new CollisionService.Obstacle(40, 20, 20, 40);
        var space = new CollisionService.Space(100, 100, List.of(wall), List.of());
        movement.move(a, 11, 8, 5, space);
        assertEquals(new Position(25, 48), a.getPosition());
        a.setPosition(new Position(30, 10));
        movement.move(a, 10, 10, 5, space);
        assertEquals(new Position(40, 10), a.getPosition());
        assertTrue(collisions.isFree(a, 35, 40, 5, space));
        assertFalse(collisions.isFree(a, 36, 40, 5, space));
        assertTrue(collisions.isFree(a, 36, 16, 5, space));
        assertFalse(collisions.isFree(a, 37, 17, 5, space));
    }

    @Test
    void skipsSelfAndDeadBodiesAndReadsLivePositions() {
        var a = actor(1, 20, 20);
        var b = actor(2, 40, 20);
        var space = new CollisionService.Space(100, 100, List.of(), List.of(
                new CollisionService.Body(a, 5), new CollisionService.Body(b, 7)));
        assertTrue(collisions.isFree(a, 20, 20, 5, space));
        assertTrue(collisions.isFree(a, 28, 20, 5, space));
        assertFalse(collisions.isFree(a, 29, 20, 5, space));
        movement.move(a, 9, 0, 5, space);
        assertEquals(new Position(20, 20), a.getPosition());
        b.setPosition(new Position(60, 20));
        assertTrue(collisions.isFree(a, 29, 20, 5, space));
        b.setPosition(new Position(40, 20));
        b.require(HealthComponent.class).applyDamage(10);
        movement.move(a, 20, 0, 5, space);
        assertEquals(new Position(40, 20), a.getPosition());
    }
}

package com.projetok.domain.movement;

import com.projetok.domain.effect.StatusEffectType;
import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.Mob;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.StatusEffectsComponent;
import com.projetok.domain.item.LootTable;
import java.util.List;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/** Verifica o escape tangencial lento sem reduzir hitboxes ou empurrar outros atores. */
class SoftSlideCollisionTest {
    private final CollisionService collisions = new CollisionService();

    // --- Escape por corpos circulares e quinas externas ---

    /** Um contato lateral converte o bloqueio em avanço tangencial com velocidade reduzida. */
    @Test void contornaCorpoSemEmpurrarEMaisDevagarQueMovimentoLivre() {
        GameEntity actor = ator(1, 20, 20);
        GameEntity blocker = ator(2, 30, 25);
        var space = espacoCorpos(actor, blocker, 5);
        Position blockerOrigin = blocker.getPosition();

        collisions.resolveSliding(actor, 4, 0, 5, space);

        Position p = actor.getPosition();
        assertTrue(p.x() > 20, "O escape precisa permitir avanço na direção pedida");
        assertTrue(p.y() < 20, "A tangente deve afastar o ator do lado do bloqueador");
        assertTrue(distancia(new Position(20, 20), p) <= 4 * 0.45 + 0.0001);
        assertTrue(collisions.isFree(actor, p.x(), p.y(), 5, space));
        assertEquals(blockerOrigin, blocker.getPosition(), "O bloqueador não pode ser empurrado");
    }

    /** Os quatro espelhamentos evitam uma preferência artificial por baixo ou pela direita. */
    @Test void escapeCircularRespeitaEspelhamentosDosContatos() {
        for (int sx : new int[] {-1, 1}) for (int sy : new int[] {-1, 1}) {
            float x = espelhar(20, sx), y = espelhar(20, sy);
            GameEntity actor = ator(1, x, y);
            GameEntity blocker = ator(2, espelhar(30, sx), espelhar(25, sy));
            var space = espacoCorpos(actor, blocker, 5);

            collisions.resolveSliding(actor, 4 * sx, 0, 5, space);

            Position p = actor.getPosition();
            assertTrue((p.x() - x) * sx > 0);
            assertTrue((p.y() - y) * sy < 0);
            assertTrue(distancia(new Position(x, y), p) <= 4 * 0.45 + 0.0001);
            assertTrue(collisions.isFree(actor, p.x(), p.y(), 5, space));
        }
    }

    /** Uma quina externa admite escape lento nos quatro lados sem encolher o raio. */
    @Test void contornaQuinaExternaNosQuatroEspelhamentos() {
        for (int sx : new int[] {-1, 1}) for (int sy : new int[] {-1, 1}) {
            float x = espelhar(33, sx), y = espelhar(32, sy);
            GameEntity actor = ator(1, x, y);
            var space = new CollisionService.Space(100, 100,
                    List.of(new CollisionService.Obstacle(40, 40, 20, 20)), List.of());

            collisions.resolveSliding(actor, 5 * sx, 0, 10, space);

            Position p = actor.getPosition();
            assertTrue((p.x() - x) * sx > 0);
            assertTrue((p.y() - y) * sy < 0);
            assertTrue(distancia(new Position(x, y), p) <= 5 * 0.45 + 0.0001);
            assertTrue(collisions.isFree(actor, p.x(), p.y(), 10, space));
        }
    }

    /** Pressões repetidas permitem sair do contato sem cruzar o corpo intermediário. */
    @Test void variosTicksPermitemEscaparSemAtravessarOutroCorpo() {
        GameEntity actor = ator(1, 20, 20);
        GameEntity blocker = ator(2, 30, 25);
        var space = espacoCorpos(actor, blocker, 5);
        for (int tick = 0; tick < 24; tick++) {
            Position before = actor.getPosition();
            collisions.resolveSliding(actor, 4, 0, 5, space);
            Position after = actor.getPosition();
            for (int sample = 0; sample <= 40; sample++) {
                float ratio = sample / 40f;
                float x = before.x() + (after.x() - before.x()) * ratio;
                float y = before.y() + (after.y() - before.y()) * ratio;
                assertTrue(collisions.isFree(actor, x, y, 5, space),
                        "O caminho entre ticks deve preservar a separação dos corpos");
            }
        }
        assertTrue(actor.getPosition().x() > 40, "O ator deve conseguir contornar o bloqueador");
        assertEquals(new Position(30, 25), blocker.getPosition());
    }

    // --- Barreiras que não admitem um desvio tangencial válido ---

    /** Um contato frontal simétrico não escolhe arbitrariamente um lado de escape. */
    @Test void contatoFrontalExatoContinuaBloqueado() {
        GameEntity actor = ator(1, 20, 20);
        GameEntity blocker = ator(2, 30, 20);

        collisions.resolveSliding(actor, 4, 0, 5, espacoCorpos(actor, blocker, 5));

        assertEquals(new Position(20, 20), actor.getPosition());
    }

    /** Paredes planas, limites e quinas internas continuam impedindo penetração. */
    @Test void paredesLimitesECantosInternosContinuamSolidos() {
        GameEntity actor = ator(1, 35, 35);
        var wall = new CollisionService.Obstacle(40, 10, 10, 70);
        var wallSpace = new CollisionService.Space(100, 100, List.of(wall), List.of());
        collisions.resolveSliding(actor, 4, 0, 5, wallSpace);
        assertEquals(new Position(35, 35), actor.getPosition());

        var cornerSpace = new CollisionService.Space(100, 100,
                List.of(wall, new CollisionService.Obstacle(10, 40, 70, 10)), List.of());
        collisions.resolveSliding(actor, 4, 4, 5, cornerSpace);
        assertEquals(new Position(35, 35), actor.getPosition());

        actor.setPosition(new Position(5, 35));
        collisions.resolveSliding(actor, -4, 0, 5,
                new CollisionService.Space(100, 100, List.of(), List.of()));
        assertEquals(new Position(5, 35), actor.getPosition());
    }

    /** A tangente de um corpo não pode ignorar outro corpo fechando a passagem. */
    @Test void doisCorposNaoPermitemForcarUmaPassagemEstreita() {
        GameEntity actor = ator(1, 22, 20);
        GameEntity upper = ator(2, 30, 14);
        GameEntity lower = ator(3, 30, 26);
        var space = new CollisionService.Space(100, 100, List.of(), List.of(
                new CollisionService.Body(actor, 5), new CollisionService.Body(upper, 5),
                new CollisionService.Body(lower, 5)));
        assertTrue(collisions.isFree(actor, 22, 20, 5, space));

        for (int tick = 0; tick < 20; tick++) collisions.resolveSliding(actor, 4, 0, 5, space);

        assertEquals(new Position(22, 20), actor.getPosition());
        assertEquals(new Position(30, 14), upper.getPosition());
        assertEquals(new Position(30, 26), lower.getPosition());
    }

    /** Uma origem já sobreposta não dispara expulsão automática nem move o outro ator. */
    @Test void origemSobrepostaNaoProvocaExpulsaoAutomatica() {
        GameEntity actor = ator(1, 20, 20);
        GameEntity blocker = ator(2, 25, 20);
        var space = espacoCorpos(actor, blocker, 5);

        collisions.resolveSliding(actor, 4, 0, 5, space);

        assertEquals(new Position(20, 20), actor.getPosition());
        assertEquals(new Position(25, 20), blocker.getPosition());
    }

    // --- Contratos compartilhados: índice, validação e imobilização ---

    /** A grade recebe a nova posição do ator sem alterar o corpo usado no contato. */
    @Test void atualizaIndiceAposEscapeMantendoOutroAtorFixo() {
        GameEntity actor = ator(1, 20, 20);
        GameEntity blocker = ator(2, 30, 25);
        var bodies = List.of(new CollisionService.Body(actor, 5), new CollisionService.Body(blocker, 5));
        var index = new SpatialBodyIndex(bodies, 1);
        var space = new CollisionService.Space(100, 100, List.of(), bodies, index);
        assertTrue(index.query(20, 25.1, 20, 25.1).stream().anyMatch(body -> body.entity() == actor));

        collisions.resolveSliding(actor, 4, 0, 5, space);

        assertTrue(actor.getPosition().y() < 20);
        assertFalse(index.query(20, 25.1, 20, 25.1).stream().anyMatch(body -> body.entity() == actor),
                "A célula antiga deve deixar de conter o ator movido");
        var p = actor.getPosition();
        assertTrue(index.query(p.x(), p.y(), p.x(), p.y()).stream().anyMatch(body -> body.entity() == actor));
        assertEquals(new Position(30, 25), blocker.getPosition());
    }

    /** A nova política mantém a rejeição de números inválidos antes de qualquer mutação. */
    @Test void rejeitaEntradasInvalidasSemAlterarPosicao() {
        GameEntity actor = ator(1, 20, 20);
        GameEntity blocker = ator(2, 30, 25);
        var space = espacoCorpos(actor, blocker, 5);
        for (float invalid : new float[] {Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY}) {
            assertThrows(IllegalArgumentException.class,
                    () -> collisions.resolveSliding(actor, invalid, 0, 5, space));
            assertThrows(IllegalArgumentException.class,
                    () -> collisions.resolveSliding(actor, 0, invalid, 5, space));
            assertThrows(IllegalArgumentException.class,
                    () -> collisions.resolveSliding(actor, 4, 0, invalid, space));
            assertEquals(new Position(20, 20), actor.getPosition());
        }
        for (float radius : new float[] {0, -1}) {
            assertThrows(IllegalArgumentException.class,
                    () -> collisions.resolveSliding(actor, 4, 0, radius, space));
            assertEquals(new Position(20, 20), actor.getPosition());
        }
    }

    /** Freeze intercepta todos os caminhos do serviço antes do escape tangencial. */
    @Test void freezeBloqueiaMovimentoMesmoComPoliticaDeDeslizamento() {
        Mob mob = new Mob(1, "Mob", new Position(20, 20), LootTable.of());
        mob.attach(new HealthComponent(10));
        var effects = new StatusEffectsComponent();
        effects.refresh(StatusEffectType.FREEZE, 1);
        mob.attach(effects);
        GameEntity blocker = ator(2, 30, 25);
        var space = espacoCorpos(mob, blocker, 5);
        var movement = new MovementService(collisions, MovementService.Response.SOFT_SLIDE);

        movement.move(mob, 4, 0, 5, space);
        movement.moveDirected(mob, new Position(1, 0), 40, 0.1f, 5, space);
        movement.moveContinuous(mob, 4, 0, 5, space);

        assertEquals(new Position(20, 20), mob.getPosition());
        assertEquals(1f, effects.remaining(StatusEffectType.FREEZE));
        assertThrows(IllegalArgumentException.class,
                () -> movement.move(mob, Float.NaN, 0, 5, space));

        effects.advance(1);
        movement.move(mob, 4, 0, 5, space);
        assertTrue(mob.getPosition().x() > 20);
        assertTrue(mob.getPosition().y() < 20);
    }

    /** A política opcional preserva posições e velocidade do movimento livre em todas as direções. */
    @Test void movimentoLivreEVelocidadeDiagonalPermanecemIguais() {
        var strict = new MovementService(collisions);
        var sliding = new MovementService(collisions, MovementService.Response.SOFT_SLIDE);
        var space = new CollisionService.Space(1000, 1000, List.of(), List.of());
        for (int x = -1; x <= 1; x++) for (int y = -1; y <= 1; y++) {
            GameEntity original = ator(1, 500, 500);
            GameEntity actor = ator(2, 500, 500);
            Position direction = strict.direction(x, y);

            strict.moveDirected(original, direction, 215, 1f / 30f, 18, space);
            sliding.moveDirected(actor, direction, 215, 1f / 30f, 18, space);

            assertEquals(original.getPosition(), actor.getPosition());
            assertEquals(x == 0 && y == 0 ? 0 : 215f / 30f,
                    distancia(new Position(500, 500), actor.getPosition()), 0.0001);
        }
    }

    /** A resolução por eixos permanece intacta quando ao menos um eixo pode avançar. */
    @Test void preservaDeslizamentoAnteriorQuandoUmEixoEstaLivre() {
        var strict = new MovementService(collisions);
        var sliding = new MovementService(collisions, MovementService.Response.SOFT_SLIDE);
        var space = new CollisionService.Space(100, 100,
                List.of(new CollisionService.Obstacle(40, 20, 20, 40)), List.of());
        GameEntity original = ator(1, 25, 40);
        GameEntity actor = ator(2, 25, 40);

        strict.move(original, 11, 8, 5, space);
        sliding.move(actor, 11, 8, 5, space);

        assertEquals(new Position(25, 48), actor.getPosition());
        assertEquals(original.getPosition(), actor.getPosition());
    }

    // --- Cenários mínimos sem Swing ou dependências externas ---

    /** Cria um ator com o componente de vida exigido pelas consultas de colisão. */
    private static GameEntity ator(int id, float x, float y) {
        GameEntity entity = new GameEntity(id, "Ator", new Position(x, y)) { };
        entity.attach(new HealthComponent(10));
        return entity;
    }

    /** Monta um cenário com o ator móvel e um bloqueador de mesmo raio. */
    private static CollisionService.Space espacoCorpos(GameEntity actor, GameEntity blocker, float radius) {
        return new CollisionService.Space(100, 100, List.of(), List.of(
                new CollisionService.Body(actor, radius), new CollisionService.Body(blocker, radius)));
    }

    /** Espelha uma coordenada em torno do centro do cenário de cem unidades. */
    private static float espelhar(float coordinate, int sign) {
        return sign > 0 ? coordinate : 100 - coordinate;
    }

    /** Mede deslocamento efetivo sem pressupor arredondamentos da projeção tangencial. */
    private static double distancia(Position a, Position b) {
        return Math.hypot(a.x() - b.x(), a.y() - b.y());
    }
}

package com.projetok.domain.movement;

import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import static org.junit.jupiter.api.Assertions.*;

/** Equivalência da busca espacial com busca linear e atualização incremental. */
class SpatialBodyIndexTest {
    /** Cria um corpo vivo com raio fixo. */
    private CollisionService.Body body(int id, float x, float y) {
        var entity = new GameEntity(id, "Corpo", new Position(x, y)) { };
        entity.attach(new HealthComponent(10));
        return new CollisionService.Body(entity, 5);
    }

    /** Mil consultas com 400 corpos coincidem com a geometria sem índice. */
    @Test
    void equivaleABuscaLinearEReduzCandidatos() {
        List<CollisionService.Body> bodies = new ArrayList<>();
        for (int i = 0; i < 400; i++) bodies.add(body(i, 20 + i % 20 * 40, 20 + i / 20 * 40));
        var index = new SpatialBodyIndex(bodies, 32);
        var indexed = new CollisionService.Space(1000, 1000, List.of(), bodies, index);
        var linear = new CollisionService.Space(1000, 1000, List.of(), bodies);
        var probe = body(500, 10, 10).entity();
        var service = new CollisionService();
        Random random = new Random(1024);
        for (int i = 0; i < 1000; i++) {
            float x = random.nextFloat() * 1000, y = random.nextFloat() * 1000;
            assertEquals(service.isFree(probe, x, y, 7, linear), service.isFree(probe, x, y, 7, indexed));
        }
        assertTrue(index.query(400, 400, 420, 420).size() < 20);
    }

    /** Resolução atualiza a célula; teleporte externo exige atualização explícita. */
    @Test
    void atualizaMovimentoETeleporteEMorte() {
        var body = body(1, 20, 20);
        var index = new SpatialBodyIndex(List.of(body), 32);
        var context = new CollisionService.Space(1000, 1000, List.of(), List.of(body), index);
        var collisions = new CollisionService();
        collisions.resolve(body.entity(), 200, 0, 5, context);
        assertFalse(index.query(10, 10, 30, 30).contains(body));
        assertTrue(index.query(210, 10, 230, 30).contains(body));
        body.entity().setPosition(new Position(400, 400));
        index.update(body.entity());
        var probe = body(2, 10, 10).entity();
        assertFalse(collisions.isFree(probe, 400, 400, 5, context));
        body.entity().require(HealthComponent.class).applyDamage(10);
        assertTrue(collisions.isFree(probe, 400, 400, 5, context));
    }

    /** A varredura consulta o trajeto inteiro e atualiza o índice ao terminar. */
    @Test
    void varreduraComIndiceEquivaleALinear() {
        var a = body(1, 20, 20);
        var b = body(2, 150, 20);
        var bodies = List.of(a, b);
        var index = new SpatialBodyIndex(bodies, 32);
        var indexed = new CollisionService.Space(1000, 1000, List.of(), bodies, index);
        var collisions = new CollisionService();
        collisions.resolveContinuous(a.entity(), 500, 0, 5, indexed);
        assertEquals(140, a.entity().getPosition().x());
        assertTrue(index.query(135, 15, 145, 25).contains(a));
    }

    /** Corpos grandes em células distantes ainda são candidatos à colisão. */
    @Test
    void raioGrandeEFronteirasDeCelulas() {
        var small = body(1, 20, 20);
        var large = new CollisionService.Body(body(2, 150, 150).entity(), 100);
        var bodies = List.of(small, large);
        var indexed = new CollisionService.Space(1000, 1000, List.of(), bodies,
                new SpatialBodyIndex(bodies, 16));
        var collisions = new CollisionService();
        assertFalse(collisions.isFree(small.entity(), 50, 150, 5, indexed));
        assertTrue(collisions.isFree(small.entity(), 45, 150, 5, indexed));
    }

    /** Consultas extremas não percorrem bilhões de células e mantêm candidatos. */
    @Test
    void fallbackEValidacaoDoIndice() {
        var body = body(1, 20, 20);
        var index = new SpatialBodyIndex(List.of(body), 32);
        assertEquals(List.of(body), index.query(-Float.MAX_VALUE, -Float.MAX_VALUE, Float.MAX_VALUE, Float.MAX_VALUE));
        assertThrows(IllegalArgumentException.class, () -> new SpatialBodyIndex(List.of(body), Float.NaN));
        assertThrows(IllegalArgumentException.class, () -> new SpatialBodyIndex(List.of(body, body), 32));
        assertThrows(IllegalArgumentException.class, () -> index.query(Double.NaN, 0, 1, 1));
        assertThrows(IllegalArgumentException.class, () -> new CollisionService.Space(100, 100, List.of(), List.of(), index));
    }
}

package com.projetok.domain.probability;

import java.util.random.RandomGenerator;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Sorteios controlados verificam probabilidades sem amostragem estatística instável. */
class ProbabilityServiceTest {
    /** Gerador da biblioteca padrão com sequência explícita e contagem de consumo. */
    private static final class Samples implements RandomGenerator {
        private final double[] values;
        private int consumed;

        /** Guarda as amostras que deverão ser consumidas em ordem. */
        private Samples(double... values) { this.values = values; }

        /** Detecta caminhos inesperados que deixem de usar a amostra double contratada. */
        @Override public long nextLong() { throw new AssertionError("Sorteio long inesperado"); }

        /** Entrega exatamente uma amostra, falhando quando o consumidor sorteia em excesso. */
        @Override public double nextDouble() {
            assertTrue(consumed < values.length, "Não deve haver sorteio extra");
            return values[consumed++];
        }
    }

    /** Chances de zero e cem por cento não consultam o gerador. */
    @Test void zeroECemPorCentoSemSorteio() {
        var samples = new Samples();
        var service = new ProbabilityService(samples);
        assertFalse(service.succeeds(0));
        assertTrue(service.succeeds(1));
        assertEquals(0, samples.consumed);
    }

    /** Comparação é estrita: 0,29 passa para 30%, mas 0,30 falha. */
    @Test void limiteExatoDeTrintaPorCento() {
        var samples = new Samples(0.29, 0.30);
        var service = new ProbabilityService(samples);
        assertTrue(service.succeeds(0.30));
        assertFalse(service.succeeds(0.30));
        assertEquals(2, samples.consumed);
    }

    /** Cada tentativa consome uma nova amostra, sem reutilizar sucesso ou falha anterior. */
    @Test void sorteiosIndependentes() {
        var samples = new Samples(0.29, 0.99, 0, 0.30);
        var service = new ProbabilityService(samples);
        assertTrue(service.succeeds(0.30));
        assertFalse(service.succeeds(0.30));
        assertTrue(service.succeeds(0.30));
        assertFalse(service.succeeds(0.30));
        assertEquals(4, samples.consumed);
    }

    /** Probabilidades inválidas são rejeitadas antes de consultar o gerador. */
    @Test void rejeitaProbabilidadesInvalidas() {
        var samples = new Samples();
        var service = new ProbabilityService(samples);
        for (double invalid : new double[] {-0.01, 1.01, Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY})
            assertThrows(IllegalArgumentException.class, () -> service.succeeds(invalid));
        assertEquals(0, samples.consumed);
        assertThrows(NullPointerException.class, () -> new ProbabilityService(null));
    }

    /** Geradores injetados também devem respeitar o contrato de amostra finita em [0, 1). */
    @Test void rejeitaAmostrasInvalidas() {
        for (double invalid : new double[] {-0.01, 1, Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY}) {
            var service = new ProbabilityService(new Samples(invalid));
            assertThrows(IllegalStateException.class, () -> service.succeeds(0.30));
        }
    }
}

package com.projetok.domain.resource;

import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.StaminaComponent;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Regressões do recurso sem Swing, rede ou mundo de prototipagem. */
class StaminaServiceTest {
    private final StaminaService service = new StaminaService();

    /** Cria uma entidade mínima com vida e vigor. */
    private GameEntity actor() {
        GameEntity entity = new GameEntity(1, "Teste", new Position(0, 0)) { };
        entity.attach(new HealthComponent(100));
        entity.attach(new StaminaComponent());
        return entity;
    }

    /** Valores iniciais e máximo configurável permanecem válidos. */
    @Test
    void valoresIniciais() {
        var stamina = new StaminaComponent();
        assertEquals(100f, stamina.current());
        assertEquals(100f, stamina.max());
        assertEquals(50f, new StaminaComponent(50f).current());
    }

    /** Custo zero é aceito inclusive sem saldo; recusa não modifica o recurso. */
    @Test
    void consumoValidoZeroEInsuficiente() {
        var entity = actor();
        var stamina = entity.require(StaminaComponent.class);
        assertTrue(service.tryConsume(entity, 20));
        assertEquals(80, stamina.current());
        assertFalse(service.tryConsume(entity, 81));
        assertEquals(80, stamina.current());
        assertTrue(service.tryConsume(entity, 80));
        assertTrue(service.tryConsume(entity, 0));
        assertFalse(service.tryConsume(entity, 1));
        assertEquals(0, stamina.current());
    }

    /** Regeneração fracionária, delta zero e saturação no máximo. */
    @Test
    void regeneracaoPorTempoELimite() {
        var entity = actor();
        var stamina = entity.require(StaminaComponent.class);
        service.tryConsume(entity, 100);
        service.regenerate(entity, 0.5f);
        assertEquals(7.5f, stamina.current());
        service.regenerate(entity, 0);
        assertEquals(7.5f, stamina.current());
        service.regenerate(entity, Float.MAX_VALUE);
        assertEquals(100, stamina.current());
        stamina.restore(Float.MAX_VALUE);
        assertEquals(100, stamina.current());
    }

    /** Toda entrada numérica inválida falha antes de modificar o componente. */
    @Test
    void rejeitaInvalidosSemMutacao() {
        var entity = actor();
        var stamina = entity.require(StaminaComponent.class);
        for (float invalid : new float[] {-1, Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY}) {
            assertThrows(IllegalArgumentException.class, () -> new StaminaComponent(invalid));
            assertThrows(IllegalArgumentException.class, () -> stamina.tryConsume(invalid));
            assertThrows(IllegalArgumentException.class, () -> stamina.restore(invalid));
            assertThrows(IllegalArgumentException.class, () -> service.tryConsume(entity, invalid));
            assertThrows(IllegalArgumentException.class, () -> service.regenerate(entity, invalid));
            assertEquals(100, stamina.current());
        }
        assertThrows(IllegalArgumentException.class, () -> new StaminaComponent(0));
    }

    /** Mortos não consomem nem regeneram, mesmo que haja saldo ou custo zero. */
    @Test
    void mortoNaoExecutaNemRegenera() {
        var entity = actor();
        service.tryConsume(entity, 20);
        entity.require(HealthComponent.class).applyDamage(100);
        assertFalse(service.tryConsume(entity, 20));
        assertFalse(service.tryConsume(entity, 0));
        service.regenerate(entity, 10);
        assertEquals(80, entity.require(StaminaComponent.class).current());
        assertThrows(IllegalArgumentException.class, () -> service.tryConsume(entity, Float.NaN));
    }
}

package com.projetok.domain.skill;

import com.projetok.domain.combat.CombatService;
import com.projetok.domain.effect.StatusEffectService;
import com.projetok.domain.effect.StatusEffectType;
import com.projetok.domain.entity.Mob;
import com.projetok.domain.entity.Player;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.RaceComponent;
import com.projetok.domain.entity.component.StaminaComponent;
import com.projetok.domain.entity.component.StatusEffectsComponent;
import com.projetok.domain.event.GameEventBus;
import com.projetok.domain.item.LootTable;
import com.projetok.domain.network.PlayerConnection;
import com.projetok.domain.probability.ProbabilityService;
import com.projetok.domain.race.DamageType;
import com.projetok.domain.race.Race;
import com.projetok.domain.race.RaceRegistry;
import com.projetok.domain.resource.StaminaService;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Map;
import java.util.random.RandomGenerator;

import static org.junit.jupiter.api.Assertions.*;

/** Regressões do Freeze aplicado por dano real, com sorteios inteiramente controlados. */
class CryostasisFreezeTest {
    private final StatusEffectService effects = new StatusEffectService();
    private final Player player = player();

    // --- Fixtures sem interface e sem adaptações do caminho de dano ---

    /** Cria um lançador mínimo com o mesmo recurso consumido na arena. */
    private static Player player() {
        Player player = new Player(1, "Lançador", new Position(100, 100), new PlayerConnection() {
            @Override public void send(Object packet) { }
            @Override public void disconnect() { }
        });
        player.attach(new HealthComponent(100));
        player.attach(new StaminaComponent());
        return player;
    }

    /** Cria um alvo neutro a gelo; a vida permite observar os cinco pulsos. */
    private static Mob mob(int id, int health) {
        Mob mob = new Mob(id, "Alvo " + id, new Position(200, 200), LootTable.of());
        mob.attach(new HealthComponent(health));
        mob.attach(new RaceComponent(RaceRegistry.withDefaults().get("demon")));
        return mob;
    }

    /** Injeta uma sequência que falha imediatamente se houver sorteios inesperados. */
    private CryostasisService service(Sequence random) {
        return new CryostasisService(new CombatService(new GameEventBus()), new StaminaService(),
                effects, new ProbabilityService(random));
    }

    /** Converte mobs em hitboxes iguais às usadas no protótipo. */
    private static List<CryostasisService.Target> targets(Mob... mobs) {
        return java.util.Arrays.stream(mobs).map(mob -> new CryostasisService.Target(mob, 19)).toList();
    }

    /** Executa o pulso imediato pelo contrato público da habilidade. */
    private CryostasisService.Result cast(CryostasisService service, List<CryostasisService.Target> targets) {
        return service.cast(player, new SkillCastCommand(CryostasisService.ID, 200, 200), 960, 640, targets);
    }

    /** Consulta efeitos ausentes como duração zero, sem exigir componente prévio na fixture. */
    private static float remaining(Mob mob) {
        return mob.get(StatusEffectsComponent.class)
                .map(component -> component.remaining(StatusEffectType.FREEZE)).orElse(0f);
    }

    /** Gerador padrão injetável com amostras predeterminadas e contagem de consumo. */
    private static final class Sequence implements RandomGenerator {
        private final double[] samples;
        private int count;

        /** Copia as amostras para impedir alteração posterior do roteiro do teste. */
        private Sequence(double... samples) { this.samples = samples.clone(); }

        /** O serviço deve usar nextDouble; outra distribuição denunciaria regressão. */
        @Override public long nextLong() { throw new AssertionError("Sorteio inesperado por nextLong"); }

        /** Retorna exatamente uma amostra por tentativa elegível. */
        @Override public double nextDouble() {
            if (count >= samples.length) throw new AssertionError("Sorteio além da sequência prevista");
            return samples[count++];
        }
    }

    // --- Elegibilidade, independência e limite estrito da probabilidade ---

    /** A mesma chance usa comparador estrito: 0,29 passa e 0,30 falha. */
    @Test void limiarDeTrintaPorCentoEhEstritoPorMob() {
        Mob first = mob(10, 120), second = mob(11, 120);
        Sequence random = new Sequence(0.29, 0.30);
        CryostasisService service = service(random);
        var result = cast(service, targets(first, second));

        assertEquals(CryostasisService.Status.CAST, result.status());
        assertEquals(2, result.hits().size());
        assertEquals(2, random.count);
        assertEquals(1f, remaining(first));
        assertEquals(0f, remaining(second));
        assertEquals(113, first.require(HealthComponent.class).current());
        assertEquals(113, second.require(HealthComponent.class).current());
        assertEquals(45f, player.require(StaminaComponent.class).current());
        assertEquals(3f, service.cooldown());
    }

    /** Cada mob recebe outro sorteio no pulso seguinte, sem compartilhar sucesso. */
    @Test void sorteiosSaoIndependentesPorMobEPorPulso() {
        Mob first = mob(10, 120), second = mob(11, 120);
        Sequence random = new Sequence(0.29, 0.80, 0.80, 0.29);
        CryostasisService service = service(random);
        var targets = targets(first, second);

        cast(service, targets);
        effects.update(first, 0.5f);
        effects.update(second, 0.5f);
        assertEquals(2, service.update(0.5f, targets).size());

        assertEquals(4, random.count);
        assertEquals(0.5f, remaining(first));
        assertEquals(1f, remaining(second));
        assertEquals(106, first.require(HealthComponent.class).current());
        assertEquals(106, second.require(HealthComponent.class).current());
    }

    /** Uma vítima duplicada na lista continua elegível uma única vez por pulso. */
    @Test void alvoDuplicadoEForaDaZonaNaoGeramSorteiosExtras() {
        Mob inside = mob(10, 120), outside = mob(11, 120);
        outside.setPosition(new Position(500, 500));
        Sequence random = new Sequence(0.29);
        var insideTarget = new CryostasisService.Target(inside, 19);
        var result = cast(service(random), List.of(insideTarget, insideTarget,
                new CryostasisService.Target(outside, 19)));

        assertEquals(1, result.hits().size());
        assertEquals(1, random.count);
        assertEquals(113, inside.require(HealthComponent.class).current());
        assertEquals(120, outside.require(HealthComponent.class).current());
        assertEquals(0f, remaining(outside));
    }

    /** Mortos e danos letais não abrem tentativas nem recebem novos efeitos. */
    @Test void mortosEDanoLetalNaoSorteiamNemAplicamFreeze() {
        Mob dead = mob(10, 120), dying = mob(11, 7);
        dead.require(HealthComponent.class).applyDamage(120);
        Sequence random = new Sequence();
        CryostasisService service = service(random);
        var targets = targets(dead, dying);

        var result = cast(service, targets);
        assertEquals(1, result.hits().size());
        assertEquals(7, result.hits().get(0).damage());
        assertTrue(dying.isDead());
        assertEquals(0f, remaining(dead));
        assertEquals(0f, remaining(dying));
        assertTrue(service.update(2.5f, targets).isEmpty());
        assertEquals(0, random.count);
    }

    /** Afinidade de gelo zero continua dano zero e não oferece controle gratuito. */
    @Test void danoZeroNaoSorteiaNemAplicaFreeze() {
        Mob immune = mob(10, 120);
        Race base = immune.race();
        immune.attach(new RaceComponent(new Race("gelo-zero", "Alvo sem dano de gelo", base.hpGrowth(),
                base.growthBonus(), Map.of(DamageType.ICE, 0.0), List.of())));
        Sequence random = new Sequence();
        CryostasisService service = service(random);
        var targets = targets(immune);

        assertEquals(0, cast(service, targets).hits().get(0).damage());
        assertEquals(4, service.update(2.5f, targets).size());
        assertEquals(120, immune.require(HealthComponent.class).current());
        assertEquals(0f, remaining(immune));
        assertEquals(0, random.count);
    }

    // --- Relógio do efeito separado do relógio da habilidade ---

    /** Novo sucesso renova um segundo; uma falha posterior preserva o tempo restante. */
    @Test void sucessoRenovaSemAcumularEFalhaNaoAlteraDuracao() {
        Mob mob = mob(10, 120);
        Sequence random = new Sequence(0.29, 0.29, 0.30);
        CryostasisService service = service(random);
        var targets = targets(mob);

        cast(service, targets);
        effects.update(mob, 0.5f);
        assertEquals(0.5f, remaining(mob));
        service.update(0.5f, targets);
        assertEquals(1f, remaining(mob));
        effects.update(mob, 0.5f);
        service.update(0.5f, targets);
        assertEquals(0.5f, remaining(mob));
        effects.update(mob, 0.5f);

        assertEquals(0f, remaining(mob));
        assertFalse(mob.require(StatusEffectsComponent.class).has(StatusEffectType.FREEZE));
        assertEquals(3, random.count);
        assertEquals(99, mob.require(HealthComponent.class).current());
    }

    /** Cinco sucessos não acrescentam dano e a expiração da zona não cria sexto sorteio. */
    @Test void cincoPulsosNormaisSemDanoExtraNemSextaTentativa() {
        Mob mob = mob(10, 120);
        Sequence random = new Sequence(0, 0, 0, 0, 0);
        CryostasisService service = service(random);
        var targets = targets(mob);
        int hits = cast(service, targets).hits().size();

        for (int i = 0; i < 4; i++) {
            effects.update(mob, 0.5f);
            var pulse = service.update(0.5f, targets);
            assertEquals(1, pulse.size());
            assertEquals(7, pulse.get(0).damage());
            assertEquals(1f, remaining(mob));
            hits += pulse.size();
        }
        effects.update(mob, 0.5f);
        assertTrue(service.update(0.5f, targets).isEmpty());
        assertTrue(service.zones().isEmpty());
        assertEquals(0.5f, remaining(mob));
        effects.update(mob, 0.5f);
        assertTrue(service.update(10f, targets).isEmpty());

        assertEquals(5, hits);
        assertEquals(5, random.count);
        assertEquals(85, mob.require(HealthComponent.class).current());
        assertEquals(0f, remaining(mob));
    }
}

package com.projetok.domain.skill;

import com.projetok.domain.combat.CombatService;
import com.projetok.domain.entity.Mob;
import com.projetok.domain.entity.Player;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.StaminaComponent;
import com.projetok.domain.entity.component.RaceComponent;
import com.projetok.domain.event.GameEventBus;
import com.projetok.domain.event.events.EntityDeathEvent;
import com.projetok.domain.item.LootTable;
import com.projetok.domain.network.PlayerConnection;
import com.projetok.domain.race.DamageType;
import com.projetok.domain.race.RaceRegistry;
import com.projetok.domain.resource.StaminaService;
import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

/** Regras da Criostase sem protótipo, interface ou banco de dados. */
class CryostasisServiceTest {
    private final GameEventBus events = new GameEventBus();
    private final CryostasisService service = new CryostasisService(new CombatService(events), new StaminaService());
    private final Player player = createPlayer();
    private final Mob mob = createMob(120, 200, 200);
    private final List<CryostasisService.Target> targets = List.of(new CryostasisService.Target(mob, 19));

    /** Monta somente os componentes exigidos pela habilidade. */
    private Player createPlayer() {
        var p = new Player(1, "Teste", new Position(100, 100), new PlayerConnection() {
            @Override public void send(Object packet) { }
            @Override public void disconnect() { }
        });
        p.attach(new HealthComponent(100)); p.attach(new StaminaComponent());
        return p;
    }

    /** Alvo mínimo: vida e raça, sem adaptadores de teste para receber dano. */
    private Mob createMob(int hp, float x, float y) {
        var m = new Mob(100, "Alvo", new Position(x, y), LootTable.of());
        m.attach(new HealthComponent(hp));
        m.attach(new RaceComponent(RaceRegistry.withDefaults().get("demon")));
        return m;
    }

    /** Executa pelo mesmo contrato de intenção usado pela interface. */
    private CryostasisService.Result cast(float x, float y) {
        return service.cast(player, new SkillCastCommand("cryostasis", x, y), 960, 640, targets);
    }

    /** Lançamento inicia cooldown, consome exatamente 55 e causa dano imediato neutro. */
    @Test void lancamentoValido() {
        var result = cast(200, 200);
        assertEquals(CryostasisService.Status.CAST, result.status());
        assertEquals(45, player.require(StaminaComponent.class).current());
        assertEquals(3, service.cooldown());
        assertEquals(113, mob.require(HealthComponent.class).current());
        assertEquals(7, result.hits().get(0).damage());
        assertEquals(1, service.zones().size());
    }

    /** Recurso insuficiente não cria zona ou cooldown nem altera saldo. */
    @Test void vigorInsuficiente() {
        new StaminaService().tryConsume(player, 50);
        assertEquals(CryostasisService.Status.STAMINA, cast(200, 200).status());
        assertEquals(50, player.require(StaminaComponent.class).current());
        assertEquals(0, service.cooldown()); assertTrue(service.zones().isEmpty());
    }

    /** Após três segundos pode lançar de novo, se houver recurso. */
    @Test void cooldownBloqueiaELibera() {
        cast(200, 200);
        assertEquals(CryostasisService.Status.COOLDOWN, cast(200, 200).status());
        assertEquals(45, player.require(StaminaComponent.class).current());
        service.update(2.99f, targets);
        assertEquals(CryostasisService.Status.COOLDOWN, cast(200, 200).status());
        service.update(0.01f, targets);
        player.require(StaminaComponent.class).restore(55);
        assertEquals(CryostasisService.Status.CAST, cast(200, 200).status());
    }

    /** Pontos no limite são preservados; pontos além são limitados sem recusa. */
    @Test void clampEAlcanceExato() {
        assertEquals(CryostasisService.Status.CAST, cast(340, 100).status());
        assertEquals(340, service.zones().get(0).x());
        service.update(3, targets); player.require(StaminaComponent.class).restore(100);
        assertEquals(CryostasisService.Status.CAST, cast(900, 600).status());
        var z = service.zones().get(0);
        assertEquals(240, Math.hypot(z.x() - 100, z.y() - 100), 0.0001);
        assertEquals(500.0 / 800, (z.y() - 100) / (z.x() - 100), 0.00001);
    }

    /** Entrada inválida nunca altera saldo, cooldown ou zonas. */
    @Test void rejeitaComandosInvalidos() {
        for (var command : List.of(new SkillCastCommand("outra", 200, 200),
                new SkillCastCommand(null, 200, 200), new SkillCastCommand("cryostasis", Float.NaN, 200),
                new SkillCastCommand("cryostasis", 200, Float.POSITIVE_INFINITY),
                new SkillCastCommand("cryostasis", Float.NEGATIVE_INFINITY, 200),
                new SkillCastCommand("cryostasis", -1, 0), new SkillCastCommand("cryostasis", 0, -1),
                new SkillCastCommand("cryostasis", 960, 0), new SkillCastCommand("cryostasis", 0, 640))) {
            assertEquals(CryostasisService.Status.INVALID, service.cast(player, command, 960, 640, targets).status());
            assertEquals(100, player.require(StaminaComponent.class).current());
            assertEquals(0, service.cooldown()); assertTrue(service.zones().isEmpty());
        }
        assertEquals(CryostasisService.Status.INVALID, service.cast(player, null, 960, 640, targets).status());
    }

    /** Morte impede criação e gasto, inclusive com comando válido. */
    @Test void jogadorMortoNaoLanca() {
        player.require(HealthComponent.class).applyDamage(100);
        assertEquals(CryostasisService.Status.DEAD, cast(200, 200).status());
        assertEquals(100, player.require(StaminaComponent.class).current());
        assertEquals(0, service.cooldown());
    }

    /** Exatamente cinco pulsos em 0, 0,5, 1, 1,5 e 2; nenhum na expiração. */
    @Test void cincoPulsosSemSexto() {
        cast(200, 200);
        assertEquals(113, mob.require(HealthComponent.class).current());
        assertTrue(service.update(0.49f, targets).isEmpty());
        assertEquals(1, service.update(0.01f, targets).size());
        assertEquals(106, mob.require(HealthComponent.class).current());
        for (int i = 0; i < 3; i++) assertEquals(1, service.update(0.5f, targets).size());
        assertEquals(85, mob.require(HealthComponent.class).current());
        assertEquals(1, service.zones().size());
        assertTrue(service.update(0.5f, targets).isEmpty());
        assertTrue(service.zones().isEmpty());
        assertTrue(service.update(10, targets).isEmpty());
        assertEquals(85, mob.require(HealthComponent.class).current());
    }

    /** Deltas de 30 Hz preservam os mesmos cinco pulsos e a expiração. */
    @Test void pulsosComDeltaDaArena() {
        int hits = cast(200, 200).hits().size();
        for (int i = 0; i < 75; i++) hits += service.update(1f / 30f, targets).size();
        assertEquals(5, hits);
        assertEquals(85, mob.require(HealthComponent.class).current());
        assertTrue(service.zones().isEmpty());
    }

    /** Passo que cruza vários instantes processa cada pulso devido exatamente uma vez. */
    @Test void passoGrandeEDeltasInvalidos() {
        cast(200, 200);
        assertEquals(4, service.update(2.5f, targets).size());
        assertEquals(85, mob.require(HealthComponent.class).current());
        for (float dt : new float[] {-1, Float.NaN, Float.POSITIVE_INFINITY})
            assertThrows(IllegalArgumentException.class, () -> service.update(dt, targets));
    }

    /** Consulta a posição em cada pulso, inclui tangência e evita duplicatas no mesmo pulso. */
    @Test void entradaSaidaETangencia() {
        mob.setPosition(new Position(305, 200));
        cast(200, 200); assertEquals(120, mob.require(HealthComponent.class).current());
        mob.setPosition(new Position(304, 200));
        assertEquals(1, service.update(0.5f, List.of(targets.get(0), targets.get(0))).size());
        assertEquals(113, mob.require(HealthComponent.class).current());
        mob.setPosition(new Position(305, 200));
        assertTrue(service.update(0.5f, targets).isEmpty());
        mob.setPosition(new Position(200, 200));
        assertEquals(1, service.update(0.5f, targets).size());
        assertEquals(106, mob.require(HealthComponent.class).current());
    }

    /** CombatService publica morte uma vez; pulsos seguintes ignoram o cadáver. */
    @Test void eventosDeMorteESomenteCombatService() {
        var dying = createMob(7, 200, 200);
        var deathCount = new AtomicInteger();
        events.subscribe(EntityDeathEvent.class, event -> { assertSame(dying, event.entity()); deathCount.incrementAndGet(); });
        var victims = List.of(new CryostasisService.Target(dying, 19));
        service.cast(player, new SkillCastCommand("cryostasis", 200, 200), 960, 640, victims);
        assertEquals(1, deathCount.get()); assertTrue(dying.isDead());
        assertTrue(service.update(2.5f, victims).isEmpty());
        assertEquals(1, deathCount.get());
    }

    /** ICE é anexado ao enum e todas as raças atuais permanecem neutras. */
    @Test void afinidadeNeutraEEnumPreservado() {
        assertEquals(6, DamageType.ICE.ordinal());
        assertEquals(List.of("PHYSICAL", "FIRE", "WATER", "HOLY", "DARK", "EARTH", "ICE"),
                java.util.Arrays.stream(DamageType.values()).map(Enum::name).toList());
        for (var race : RaceRegistry.withDefaults().all()) assertEquals(1.0, race.affinityFor(DamageType.ICE));
    }

    /** A zona não acompanha o lançador e continua ativa se ele morrer. */
    @Test void zonaFixaAposMoverOuMorrer() {
        cast(200, 200);
        player.setPosition(new Position(700, 500));
        player.require(HealthComponent.class).applyDamage(100);
        service.update(0.5f, targets);
        assertEquals(200, service.zones().get(0).x());
        assertEquals(200, service.zones().get(0).y());
        assertEquals(106, mob.require(HealthComponent.class).current());
    }
}

package com.projetok.domain.skill;

import com.projetok.domain.ai.PassiveBehavior;
import com.projetok.domain.combat.CombatService;
import com.projetok.domain.effect.StatusEffectService;
import com.projetok.domain.effect.StatusEffectType;
import com.projetok.domain.entity.Mob;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.StaminaComponent;
import com.projetok.domain.entity.component.StatusEffectsComponent;
import com.projetok.domain.event.GameEventBus;
import com.projetok.domain.factory.MobArchetype;
import com.projetok.domain.factory.MobFactory;
import com.projetok.domain.item.LootTable;
import com.projetok.domain.movement.CollisionCategory;
import com.projetok.domain.movement.CollisionService;
import com.projetok.domain.movement.MovementService;
import com.projetok.domain.movement.SpatialBodyIndex;
import com.projetok.domain.probability.ProbabilityService;
import com.projetok.domain.progression.VitalityService;
import com.projetok.domain.race.RaceRegistry;
import com.projetok.domain.resource.StaminaService;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;
import java.util.random.RandomGenerator;

import static com.projetok.domain.skill.LightningStepTestFixtures.*;
import static org.junit.jupiter.api.Assertions.*;

/** Regride sequências de serviços reais sem relógio do SO, interface ou novos baselines. */
class DomainSequenceRegressionTest {
    private static final float DT = 1f / 30f;
    private static final float MOB_RADIUS = 19f;
    private static final float WALK_SPEED = 215f;

    // --- Dash, dano recebido e retorno à colisão normal ---

    /** Travessia não causa dano nem invulnerabilidade; depois, caminhada e ataque básico continuam normais. */
    @Test
    void atravessaAtorRecebeDanoERetomaMovimentoEAtaqueSemCusto() {
        var player = player(100, 100);
        var mob = mob(175, 100);
        var collisions = new CollisionService();
        var movement = new MovementService(collisions);
        var combat = new CombatService(new GameEventBus());
        var bodies = List.of(new CollisionService.Body(player, RADIUS), new CollisionService.Body(mob, MOB_RADIUS));
        var index = new SpatialBodyIndex(bodies, 16);
        var space = new CollisionService.Space(960, 640, List.of(), bodies, index);
        var dash = selectiveService();

        assertEquals(LightningStepService.Status.STARTED, dash.cast(player, right(), RADIUS, space));
        dash.update(player, DT, RADIUS, space);
        assertEquals(120, player.getPosition().x(), 0.0001);
        assertEquals(120, mob.require(HealthComponent.class).current(), "Mover não aplica dano aos corpos atravessados");
        assertTrue(Math.abs(mob.getPosition().x() - player.getPosition().x()) <= 58,
                "O atacante está no alcance usado pela arena durante o dash");
        assertEquals(6, combat.attack(mob, player));
        assertEquals(94, player.require(HealthComponent.class).current(), "O dash não concede invulnerabilidade");
        for (int i = 1; i < 8; i++) dash.update(player, DT, RADIUS, space);

        assertFalse(dash.active());
        assertFalse(dash.awaitingLanding());
        assertEquals(new Position(250, 100), player.getPosition());
        assertEquals(120, mob.require(HealthComponent.class).current());
        assertTrue(mob.require(StatusEffectsComponent.class).snapshot().isEmpty());
        for (int i = 0; i < 5; i++) {
            movement.moveDirected(player, new Position(-1, 0), WALK_SPEED, DT, RADIUS, space);
        }
        var touching = player.getPosition();
        assertTrue(touching.x() - mob.getPosition().x() >= RADIUS + MOB_RADIUS);
        movement.moveDirected(player, new Position(-1, 0), WALK_SPEED, DT, RADIUS, space);
        assertEquals(touching, player.getPosition(), "A caminhada volta a ser bloqueada pelo mesmo ator");
        assertTrue(collisions.isFree(player, touching.x(), touching.y(), RADIUS, space));

        assertEquals(15, combat.attack(player, mob));
        assertEquals(105, mob.require(HealthComponent.class).current());
        assertEquals(65, player.require(StaminaComponent.class).current(), "Andar e atacar não consomem vigor");
        assertEquals(94, player.require(HealthComponent.class).current());
    }

    // --- Categoria de cenário não altera dano, sorteios ou temporizadores ---

    /** Trocar somente a categoria conserva os cinco pulsos, Freeze, ataques e estados quadro a quadro. */
    @Test
    void categoriaDeObstaculoNaoAlteraSequenciaDeCombateECongelamento() {
        var solid = combatTrace(CollisionCategory.SOLID_OBSTACLE);
        var soft = combatTrace(CollisionCategory.SOFT_OBSTACLE);
        assertEquals(solid, soft, "Geometria idêntica não muda dano, duração ou probabilidades do combate");
        assertEquals(5, solid.draws());
        assertEquals(5, solid.hits());
        assertEquals(70, solid.frames().get(solid.frames().size() - 1).mobHp(),
                "Cinco pulsos de sete e um ataque desarmado de quinze");
        assertEquals(88, solid.frames().get(solid.frames().size() - 1).playerHp(),
                "Dois ataques de seis foram permitidos enquanto o mob estava congelado");
        assertTrue(solid.frames().stream().filter(frame -> frame.freeze() > 0)
                .allMatch(frame -> frame.mobPosition().equals(new Position(250, 100))));
        assertTrue(solid.frames().get(solid.frames().size() - 1).mobPosition().y() < 100,
                "Após expirar o Freeze, a perseguição volta a deslocar o mob");
    }

    // --- Recuperação ocupada, grade espacial e movimento no tick seguinte ---

    /** Um corpo móvel com coordenada fracionária exige recuo e a grade continua correta após caminhar. */
    @Test
    void destinoOcupadoPorCorpoMovelCorrigeIndiceERetomaMovimento() {
        var player = player(100, 100);
        var mob = mob(400, 100);
        var collisions = new CollisionService();
        var movement = new MovementService(collisions);
        var stamina = new StaminaService();
        var playerBody = new CollisionService.Body(player, RADIUS);
        var mobBody = new CollisionService.Body(mob, MOB_RADIUS);
        var bodies = List.of(playerBody, mobBody);
        var index = new SpatialBodyIndex(bodies, 16);
        var indexed = new CollisionService.Space(960, 640, List.of(), bodies, index);
        var reference = new CollisionService.Space(960, 640, List.of(), bodies);
        var dash = selectiveService();
        assertEquals(LightningStepService.Status.STARTED, dash.cast(player, right(), RADIUS, indexed));
        dash.update(player, 0.1f, RADIUS, indexed);

        float movingTargetX = Math.nextAfter(250f, Double.POSITIVE_INFINITY);
        mob.setPosition(new Position(movingTargetX, 100));
        index.update(mob);
        dash.update(player, 0.15f, RADIUS, indexed);
        var recovered = player.getPosition();
        assertEquals(movingTargetX - RADIUS - MOB_RADIUS, recovered.x(), Math.ulp(movingTargetX) * 2);
        assertTrue(collisions.isFree(player, recovered.x(), recovered.y(), RADIUS, indexed));
        assertFalse(collisions.isFree(player, Math.nextAfter(recovered.x(), Double.POSITIVE_INFINITY),
                recovered.y(), RADIUS, indexed), "O próximo float já penetraria o corpo atual");
        assertTrue(index.query(recovered.x(), recovered.y(), recovered.x(), recovered.y()).contains(playerBody));
        assertFalse(index.query(250, 100, 250, 100).contains(playerBody), "A célula anterior não retém o jogador");

        for (int i = 0; i < 20; i++) {
            dash.update(player, DT, RADIUS, indexed);
            stamina.regenerate(player, DT);
            movement.moveDirected(player, i < 12 ? new Position(-1, 0) : new Position(0, 1),
                    WALK_SPEED, DT, RADIUS, indexed);
        }
        var walking = player.getPosition();
        assertEquals(recovered.x() - WALK_SPEED * DT * 12, walking.x(), 0.0002);
        assertEquals(100 + WALK_SPEED * DT * 8, walking.y(), 0.0002);
        assertTrue(index.query(walking.x(), walking.y(), walking.x(), walking.y()).contains(playerBody));
        assertFalse(index.query(recovered.x(), recovered.y(), recovered.x(), recovered.y()).contains(playerBody));
        assertTrue(index.query(movingTargetX, 100, movingTargetX, 100).contains(mobBody));
        for (var point : List.of(walking, recovered, new Position(movingTargetX, 100),
                new Position(movingTargetX + RADIUS + MOB_RADIUS, 100), new Position(100, 100))) {
            assertEquals(collisions.isFree(player, point.x(), point.y(), RADIUS, reference),
                    collisions.isFree(player, point.x(), point.y(), RADIUS, indexed),
                    "O índice mantém o mesmo resultado da consulta sem grade após recuo e WASD");
        }
        assertEquals(75, player.require(StaminaComponent.class).current());
        assertEquals(120, mob.require(HealthComponent.class).current());
        assertFalse(dash.active());
        assertFalse(dash.awaitingLanding());
    }

    // --- Vizinhos float de tangência e borda ---

    /** Um ULP distingue origem válida de sobreposição; o dash conserva raio, custo e duração. */
    @Test
    void floatsAdjacentesATangenciaELimiteContinuamSeguros() {
        var collisions = new CollisionService();
        var wall = new CollisionService.Space(960, 640,
                List.of(new CollisionService.Obstacle(200, 50, 15, 100)), List.of());
        float tangent = 182;
        float outside = Math.nextAfter(tangent, Double.NEGATIVE_INFINITY);
        float inside = Math.nextAfter(tangent, Double.POSITIVE_INFINITY);
        var player = player(outside, 100);
        assertTrue(collisions.isFree(player, outside, 100, RADIUS, wall));
        assertTrue(collisions.isFree(player, tangent, 100, RADIUS, wall));
        assertFalse(collisions.isFree(player, inside, 100, RADIUS, wall));
        var dash = selectiveService();
        assertEquals(LightningStepService.Status.STARTED, dash.cast(player, right(), RADIUS, wall));
        var stopped = dash.update(player, 0.25f, RADIUS, wall);
        assertEquals(tangent, player.getPosition().x());
        assertTrue(stopped.blocked());
        assertFalse(dash.active());
        assertEquals(65, player.require(StaminaComponent.class).current());

        var invalid = player(inside, 100);
        var refused = selectiveService();
        assertEquals(LightningStepService.Status.INVALID, refused.cast(invalid, right(), RADIUS, wall));
        assertEquals(new Position(inside, 100), invalid.getPosition());
        assertEquals(100, invalid.require(StaminaComponent.class).current());
        assertEquals(0, refused.cooldown());

        var empty = emptySpace();
        float nearBorder = Math.nextAfter(RADIUS, Double.POSITIVE_INFINITY);
        var edgePlayer = player(nearBorder, 100);
        assertFalse(collisions.isFree(edgePlayer, Math.nextAfter(RADIUS, Double.NEGATIVE_INFINITY), 100, RADIUS, empty));
        assertTrue(collisions.isFree(edgePlayer, RADIUS, 100, RADIUS, empty));
        var edgeDash = selectiveService();
        assertEquals(LightningStepService.Status.STARTED, edgeDash.cast(edgePlayer,
                new SkillCastCommand(LightningStepService.ID, 0, 100), RADIUS, empty));
        edgeDash.update(edgePlayer, 0.25f, RADIUS, empty);
        assertEquals(new Position(RADIUS, 100), edgePlayer.getPosition());
        assertFalse(edgeDash.active());
        assertFalse(edgeDash.awaitingLanding());
        assertEquals(65, edgePlayer.require(StaminaComponent.class).current());
        assertEquals(3.75f, edgeDash.cooldown());
    }

    // --- Fixtures e roteiros determinísticos ---

    /** Posiciona o alvo sem alterar a direção positiva fixada no lançamento. */
    private static SkillCastCommand right() { return new SkillCastCommand(LightningStepService.ID, 800, 100); }

    /** Cria o mesmo arquétipo real da arena, incluindo combate, raça, vida e efeitos. */
    private static Mob mob(float x, float y) {
        var archetype = new MobArchetype(RaceRegistry.withDefaults().get("demon"), "Alvo de regressão",
                1, 12, 4, 9, null, LootTable.of(), new PassiveBehavior());
        return new MobFactory(new VitalityService()).spawn(200, archetype, new Position(x, y));
    }

    /** Captura somente valores, permitindo comparar as duas categorias sem hashes de apresentação. */
    private record Frame(int mobHp, int playerHp, float freeze, Position mobPosition) { }

    /** Resultado imutável do roteiro de combate, incluindo o número exato de sorteios e pulsos. */
    private record Trace(List<Frame> frames, int draws, int hits) {
        /** Preserva a sequência para comparações posteriores sem compartilhar a lista mutável. */
        private Trace { frames = List.copyOf(frames); }
    }

    /** Repete cinco pulsos e tentativas de movimento; a única variável é a categoria do mesmo retângulo. */
    private static Trace combatTrace(CollisionCategory category) {
        var player = player(200, 100);
        var mob = mob(250, 100);
        var effects = new StatusEffectService();
        var combat = new CombatService(new GameEventBus());
        var sequence = new ControlledSequence(0.29, 0.30, 0.29, 0.30, 0.99);
        var cryo = new CryostasisService(combat, new StaminaService(), effects, new ProbabilityService(sequence));
        var movement = new MovementService(new CollisionService());
        var bodies = List.of(new CollisionService.Body(player, RADIUS), new CollisionService.Body(mob, MOB_RADIUS));
        var space = new CollisionService.Space(960, 640,
                List.of(new CollisionService.Obstacle(220, 70, 10, 60, category)), bodies,
                new SpatialBodyIndex(bodies, 16));
        var targets = List.of(new CryostasisService.Target(mob, MOB_RADIUS));
        var result = cryo.cast(player, new SkillCastCommand(CryostasisService.ID, 250, 100), 960, 640, targets);
        assertEquals(CryostasisService.Status.CAST, result.status());
        assertEquals(7, result.hits().get(0).damage());
        assertEquals(1, remaining(mob));
        assertEquals(6, combat.attack(mob, player));
        var frames = new ArrayList<Frame>();
        frames.add(frame(mob, player.require(HealthComponent.class).current()));
        int hits = result.hits().size();
        for (int tick = 1; tick <= 75; tick++) {
            effects.update(mob, DT);
            var pulse = cryo.update(DT, targets);
            for (var hit : pulse) assertEquals(7, hit.damage());
            hits += pulse.size();
            movement.moveDirected(mob, new Position(0, -1), 92, DT, MOB_RADIUS, space);
            if (tick == 20) {
                assertTrue(remaining(mob) > 0);
                assertEquals(6, combat.attack(mob, player));
            }
            frames.add(frame(mob, player.require(HealthComponent.class).current()));
        }
        assertTrue(cryo.zones().isEmpty());
        assertEquals(0, remaining(mob));
        assertEquals(15, combat.attack(player, mob));
        frames.add(frame(mob, player.require(HealthComponent.class).current()));
        return new Trace(frames, sequence.index, hits);
    }

    /** Lê somente os valores usados nas invariantes do roteiro. */
    private static Frame frame(Mob mob, int playerHp) {
        return new Frame(mob.require(HealthComponent.class).current(), playerHp, remaining(mob), mob.getPosition());
    }

    /** A fábrica anexa o armazenamento de efeitos antes de iniciar a sequência. */
    private static float remaining(Mob mob) { return mob.require(StatusEffectsComponent.class).remaining(StatusEffectType.FREEZE); }

    /** Falha imediatamente se algum caminho consumir aleatoriedade fora dos cinco pulsos planejados. */
    private static final class ControlledSequence implements RandomGenerator {
        private final double[] samples;
        private int index;

        /** Copia o roteiro para impedir alterações externas durante o teste. */
        private ControlledSequence(double... samples) { this.samples = samples.clone(); }

        /** O contrato reutilizável de probabilidade usa amostras uniformes de double. */
        @Override public long nextLong() { throw new AssertionError("Distribuição inesperada"); }

        /** Entrega uma tentativa independente por pulso e denuncia tentativas extras. */
        @Override public double nextDouble() {
            if (index >= samples.length) throw new AssertionError("Sorteio extra fora do roteiro");
            return samples[index++];
        }
    }
}

package com.projetok.domain.skill;

import com.projetok.domain.entity.DialogueScript;
import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.Mob;
import com.projetok.domain.entity.Npc;
import com.projetok.domain.entity.Position;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.StaminaComponent;
import com.projetok.domain.entity.component.StatusEffectsComponent;
import com.projetok.domain.item.LootTable;
import com.projetok.domain.movement.CollisionCategory;
import com.projetok.domain.movement.CollisionService;
import com.projetok.domain.movement.SpatialBodyIndex;
import java.util.List;
import org.junit.jupiter.api.Test;
import static com.projetok.domain.skill.LightningStepTestFixtures.*;
import static org.junit.jupiter.api.Assertions.*;

/** Passagem seletiva e recuperação autoritativa sem alterar os testes sólidos anteriores. */
class LightningStepSelectiveCollisionTest {
    // --- Montagem de comandos e corpos ---

    /** Aponta à direita sem limitar o orçamento de 150 unidades ao cursor. */
    private static SkillCastCommand right() {
        return new SkillCastCommand(LightningStepService.ID, 800f, 100f);
    }

    /** Cria um mob vivo que permite verificar dano e efeitos colaterais. */
    private static Mob mob(float x, float y) {
        var mob = new Mob(200, "Alvo de passagem", new Position(x, y), LootTable.of());
        mob.attach(new HealthComponent(120));
        mob.attach(new StatusEffectsComponent());
        return mob;
    }

    /** Cria um arbusto retangular para a mesma geometria usada pelos sólidos. */
    private static CollisionService.Obstacle brush(float x, float y, float width, float height) {
        return new CollisionService.Obstacle(x, y, width, height, CollisionCategory.SOFT_OBSTACLE);
    }

    /** Confirma a validade normal, inclusive após uma correção de pouso. */
    private static void assertNormalPosition(GameEntity entity, CollisionService.Space space) {
        var p = entity.getPosition();
        assertTrue(new CollisionService().isFree(entity, p.x(), p.y(), RADIUS, space),
                () -> "Posição final precisa estar livre na política normal: " + p);
    }

    // --- Passagem e regras preservadas ---

    /** Atores de classes distintas são atravessados sem deslocamento ou dano. */
    @Test void atravessaMobJogadorENpcSemAlterarOsAtores() {
        var mob = mob(175f, 100f);
        var otherPlayer = player(175f, 100f);
        var npc = new Npc(300, "Vendedor", new Position(175f, 100f), DialogueScript.of("Vendedor"));
        // O NPC de diálogo não precisa ganhar componentes de combate para ser atravessado.
        for (GameEntity actor : List.of(mob, otherPlayer, npc)) {
            var player = player(100f, 100f);
            var service = selectiveService();
            var space = new CollisionService.Space(960f, 640f, List.of(), List.of(
                    new CollisionService.Body(player, RADIUS), new CollisionService.Body(actor, 19f)));
            assertEquals(LightningStepService.Status.STARTED, service.cast(player, right(), RADIUS, space));
            service.update(player, 0.125f, RADIUS, space);
            assertEquals(new Position(175f, 100f), player.getPosition());
            assertTrue(service.active());
            service.update(player, 0.125f, RADIUS, space);
            assertEquals(new Position(250f, 100f), player.getPosition());
            assertEquals(new Position(175f, 100f), actor.getPosition());
            assertEquals(100, player.require(HealthComponent.class).current());
            assertEquals(65f, player.require(StaminaComponent.class).current());
            assertEquals(3.75f, service.cooldown());
            assertFalse(service.active());
            assertFalse(service.awaitingLanding());
            assertNormalPosition(player, space);
        }
        assertEquals(120, mob.require(HealthComponent.class).current());
        assertTrue(mob.require(StatusEffectsComponent.class).snapshot().isEmpty());
        assertEquals(100, otherPlayer.require(HealthComponent.class).current());
    }

    /** Arbustos usam a mesma forma retangular, mas não bloqueiam o avanço seletivo. */
    @Test void atravessaArbustoSemMudarDistanciaDuracaoOuCusto() {
        var player = player(100f, 100f);
        var service = selectiveService();
        var space = new CollisionService.Space(960f, 640f,
                List.of(brush(150f, 80f, 30f, 40f)), List.of());
        assertEquals(LightningStepService.Status.STARTED, service.cast(player, right(), RADIUS, space));
        service.update(player, 0.1f, RADIUS, space);
        assertEquals(160f, player.getPosition().x(), 0.0001f);
        service.update(player, 0.1f, RADIUS, space);
        assertEquals(220f, player.getPosition().x(), 0.0001f);
        service.update(player, 0.2f, RADIUS, space);
        assertEquals(new Position(250f, 100f), player.getPosition());
        assertFalse(service.active());
        assertEquals(0f, service.remaining());
