package com.projetok.domain.progression;

import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.component.RaceComponent;
import com.projetok.domain.entity.component.StatsComponent;
import com.projetok.domain.event.GameEventBus;
import com.projetok.domain.event.events.EntityLeveledUpEvent;
import com.projetok.domain.race.Race;

import java.util.Objects;

/**
 * Substitui a lógica hoje partida entre Entity.levelUp(...) e PlayerConfiguration — e
 * adiciona o bônus racial automático (ex.: Demônio +2 de força por nível, compensando a
 * fraqueza a dano Sagrado/Água).
 */
public final class LevelUpService {

    private final LevelingRules levelingRules;
    private final VitalityService vitalityService;

    public LevelUpService(LevelingRules levelingRules, VitalityService vitalityService) {
        this.levelingRules = Objects.requireNonNull(levelingRules, "levelingRules");
        this.vitalityService = Objects.requireNonNull(vitalityService, "vitalityService");
    }

    public void applyLevelUp(GameEntity entity, GameEventBus eventBus) {
        StatsComponent currentStats = entity.require(StatsComponent.class);
        Race race = entity.require(RaceComponent.class).race();

        int pointsGained = levelingRules.pointsForLevel(currentStats.level() + 1);
        StatsComponent newStats = currentStats.applyLevelUp(pointsGained, race.growthBonus());
        entity.attach(newStats);

        vitalityService.recalculate(entity); // novo nível pode mudar o HP máximo, mesmo sem item novo
        race.traits().forEach(trait -> trait.onLevelUp(entity));

        eventBus.publish(new EntityLeveledUpEvent(entity, newStats.level()));
    }
}

package com.projetok.domain.progression;

import com.projetok.domain.entity.GameEntity;
import com.projetok.domain.entity.component.EquipmentComponent;
import com.projetok.domain.entity.component.HealthComponent;
import com.projetok.domain.entity.component.RaceComponent;
import com.projetok.domain.entity.component.StatsComponent;
import com.projetok.domain.race.Race;

/**
 * Único lugar que decide o HP máximo de uma entidade: nível (via StatsComponent) e itens
 * (via EquipmentComponent), sempre passados pela curva da raça (HpGrowth). Chamado depois
 * de criar a entidade, depois de level up e depois de equipar/desequipar — nunca em
 * nenhum outro lugar.
 */
public final class VitalityService {

    public void recalculate(GameEntity entity) {
        StatsComponent stats = entity.require(StatsComponent.class);
        Race race = entity.require(RaceComponent.class).race();
        int itemHpBonus = entity.get(EquipmentComponent.class)
                                 .map(EquipmentComponent::totalHpBonus)
                                 .orElse(0);

        int newMax = race.hpGrowth().computeMaxHp(stats.level(), itemHpBonus);
        entity.require(HealthComponent.class).recalculateMax(newMax);
    }
}

package com.projetok.domain.race;

/** Bônus automático de atributo por nível, específico da raça (ex.: fraqueza elemental compensada aqui). */
public record AttributeGrowth(int strength, int intelligence, int agility) {

    public static final AttributeGrowth NONE = new AttributeGrowth(0, 0, 0);
}

package com.projetok.domain.race;

public enum DamageType {
    PHYSICAL,
    FIRE,
    WATER,
    HOLY,
    DARK,
    EARTH,
    ICE
}

package com.projetok.domain.race;

/**
 * As DUAS únicas fontes de HP máximo do jogo: nível (hpPerLevel) e itens (itemBonusHp).
 * Não existe (e não deve existir) nenhum outro caminho de código que altere HP máximo.
 */
public record HpGrowth(int baseHp, int hpPerLevel) {

    public HpGrowth {
        if (baseHp < 1) throw new IllegalArgumentException("baseHp deve ser >= 1");
        if (hpPerLevel < 0) throw new IllegalArgumentException("hpPerLevel não pode ser negativo");
    }

    public int computeMaxHp(int level, int itemBonusHp) {
        return baseHp + hpPerLevel * (level - 1) + Math.max(0, itemBonusHp);
    }
}

package com.projetok.domain.race;

import java.util.List;
import java.util.Map;

/**
 * Sucessora de Human.java/Demon.java como CLASSES. Raça agora é dado, não posição na
 * hierarquia de herança — trocar o tema do jogo (demônio -> espírito) é só trocar os dados
 * carregados aqui (ver RaceRegistry), sem tocar em Player, Mob, CombatService ou qualquer
 * outra classe de domínio.
 */
public final class Race {

    private final String id;
    private final String displayName;
    private final HpGrowth hpGrowth;
    private final AttributeGrowth growthBonus;
    private final Map<DamageType, Double> affinities;
    private final List<RacialTrait> traits;

    public Race(String id, String displayName, HpGrowth hpGrowth, AttributeGrowth growthBonus,
                Map<DamageType, Double> affinities, List<RacialTrait> traits) {
        this.id = id;
        this.displayName = displayName;
        this.hpGrowth = hpGrowth;
        this.growthBonus = growthBonus;
        this.affinities = Map.copyOf(affinities);
        this.traits = List.copyOf(traits);
    }

    /** 1.0 = neutro, acima de 1.0 = fraqueza (recebe mais dano), abaixo = resistência. */
    public double affinityFor(DamageType type) {
        return affinities.getOrDefault(type, 1.0);
    }

    public String id() {
        return id;
    }

    public String displayName() {
        return displayName;
    }

    public HpGrowth hpGrowth() {
        return hpGrowth;
    }

    public AttributeGrowth growthBonus() {
        return growthBonus;
    }

    public List<RacialTrait> traits() {
        return traits;
    }
}

package com.projetok.domain.race;

import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Conjunto de raças padrão para desenvolvimento/testes locais. Em produção, isto deve ser
 * substituído por carga a partir da tabela `races` no Postgres (ver Pilar 2 do documento de
 * arquitetura) — nenhuma outra classe do domínio depende de como esses dados chegam até
 * aqui, só desta interface (RaceRegistry.get(id)).
 */
public final class RaceRegistry {

    private final Map<String, Race> races;

    private RaceRegistry(Map<String, Race> races) {
        this.races = races;
    }

    public static RaceRegistry of(Collection<Race> races) {
        Map<String, Race> byId = races.stream()
            .collect(Collectors.toMap(Race::id, race -> race));
        return new RaceRegistry(byId);
    }

    public static RaceRegistry withDefaults() {
        return of(List.of(
            new Race(
                "human", "Humano",
                new HpGrowth(100, 10),
                AttributeGrowth.NONE,
                Map.of(),
                List.of()
            ),
            new Race(
                "demon", "Demônio",
                new HpGrowth(120, 14),
                new AttributeGrowth(2, 0, 0),
                Map.of(DamageType.HOLY, 1.5, DamageType.WATER, 1.3),
                List.of()
            ),
            new Race(
                "spirit", "Espírito",
                new HpGrowth(80, 8),
                new AttributeGrowth(0, 3, 1),
                Map.of(DamageType.PHYSICAL, 1.4, DamageType.HOLY, 0.6),
                List.of()
            )
        ));
    }

    public Race get(String id) {
        Race race = races.get(id);
        if (race == null) {
            throw new IllegalArgumentException("Raça desconhecida: " + id);
        }
        return race;
    }

    public Collection<Race> all() {
        return races.values();
    }
}

